-- ----------------------------------------------------------------------------
-- StepFunctions: Many-to-many Step/Function semantics normalized into an ERB junction table.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS step_functions (
  step_function_id                    TEXT                 PRIMARY KEY          -- Stored logical identifier for one StepFunctions row.
);
ALTER TABLE step_functions ADD COLUMN IF NOT EXISTS step TEXT;                                      -- Step side of the relationship.
ALTER TABLE step_functions ADD COLUMN IF NOT EXISTS function TEXT;                                  -- Function side of the relationship.
COMMENT ON TABLE step_functions IS 'Many-to-many Step/Function semantics normalized into an ERB junction table.';
COMMENT ON COLUMN step_functions.step_function_id IS 'Stored logical identifier for one StepFunctions row.';
COMMENT ON COLUMN step_functions.step IS 'Step side of the relationship.';
COMMENT ON COLUMN step_functions.function IS 'Function side of the relationship.';

-- ----------------------------------------------------------------------------
-- StepTools: Many-to-many Step/Tool semantics normalized into an ERB junction table.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS step_tools (
  step_tool_id                        TEXT                 PRIMARY KEY          -- Stored logical identifier for one StepTools row.
);
ALTER TABLE step_tools ADD COLUMN IF NOT EXISTS step TEXT;                                          -- Step side of the relationship.
ALTER TABLE step_tools ADD COLUMN IF NOT EXISTS tool TEXT;                                          -- Tool side of the relationship.
