COMMENT ON COLUMN step_tools.tool IS 'Tool side of the relationship.';

-- ----------------------------------------------------------------------------
-- Requirements: Normative requirements applied to procedures, steps, or transitions. Maps to pko:Requirement and pko:hasRequirement.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS requirements (
  requirement_id                      TEXT                 PRIMARY KEY          -- Stored logical identifier for one Requirements row.
);
ALTER TABLE requirements ADD COLUMN IF NOT EXISTS label TEXT;                                       -- Requirement label.
ALTER TABLE requirements ADD COLUMN IF NOT EXISTS requirement_type TEXT;                            -- Controlled requirement type; maps to pko:hasRequirementType.
ALTER TABLE requirements ADD COLUMN IF NOT EXISTS statement TEXT;                                   -- Normative requirement statement.
ALTER TABLE requirements ADD COLUMN IF NOT EXISTS rationale TEXT;                                   -- Why the requirement exists.
ALTER TABLE requirements ADD COLUMN IF NOT EXISTS is_blocking BOOLEAN;                              -- TRUE when unsatisfied requirement blocks execution or approval.
ALTER TABLE requirements ADD COLUMN IF NOT EXISTS has_computed_witness BOOLEAN;                     -- Whether a computed predicate in this rulebook evaluates this requirement, as opposed to it being satisfied by human assertion only.
ALTER TABLE requirements ADD COLUMN IF NOT EXISTS witness_field_name TEXT;                          -- The fully-qualified Table.Field of the predicate that computes this requirement, when one exists.
ALTER TABLE requirements ADD COLUMN IF NOT EXISTS minimum_sample_for_assurance INTEGER;             -- The number of clean evaluations this control must accumulate before its silence counts as evidence.
ALTER TABLE requirements ADD COLUMN IF NOT EXISTS accountable_role TEXT;                            -- The role answerable for this control operating as designed.
ALTER TABLE requirements ADD COLUMN IF NOT EXISTS controlled_term TEXT;                             -- Controlled vocabulary term this requirement's concept maps to, if any.
ALTER TABLE requirements ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                           -- Exact PKO class IRI.
ALTER TABLE requirements ADD COLUMN IF NOT EXISTS regulatory_framework TEXT;                        -- Regulation that imposes the requirement.
COMMENT ON TABLE requirements IS 'Normative requirements applied to procedures, steps, or transitions. Maps to pko:Requirement and pko:hasRequirement.';
COMMENT ON COLUMN requirements.requirement_id IS 'Stored logical identifier for one Requirements row.';
COMMENT ON COLUMN requirements.label IS 'Requirement label.';
COMMENT ON COLUMN requirements.requirement_type IS 'Controlled requirement type; maps to pko:hasRequirementType.';
COMMENT ON COLUMN requirements.statement IS 'Normative requirement statement.';
COMMENT ON COLUMN requirements.rationale IS 'Why the requirement exists.';
COMMENT ON COLUMN requirements.is_blocking IS 'TRUE when unsatisfied requirement blocks execution or approval.';
COMMENT ON COLUMN requirements.has_computed_witness IS 'Whether a computed predicate in this rulebook evaluates this requirement, as opposed to it being satisfied by human assertion only.';
COMMENT ON COLUMN requirements.witness_field_name IS 'The fully-qualified Table.Field of the predicate that computes this requirement, when one exists.';
COMMENT ON COLUMN requirements.minimum_sample_for_assurance IS 'The number of clean evaluations this control must accumulate before its silence counts as evidence.';
COMMENT ON COLUMN requirements.accountable_role IS 'The role answerable for this control operating as designed.';
COMMENT ON COLUMN requirements.controlled_term IS 'Controlled vocabulary term this requirement''s concept maps to, if any.';
COMMENT ON COLUMN requirements.semantic_type_iri IS 'Exact PKO class IRI.';
COMMENT ON COLUMN requirements.regulatory_framework IS 'Regulation that imposes the requirement.';

-- ----------------------------------------------------------------------------
-- StepRequirements: Many-to-many Step/Requirement semantics normalized into an ERB junction table.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS step_requirements (
  step_requirement_id                 TEXT                 PRIMARY KEY          -- Stored logical identifier for one StepRequirements row.
);
ALTER TABLE step_requirements ADD COLUMN IF NOT EXISTS step TEXT;                                   -- Step side of the relationship.
ALTER TABLE step_requirements ADD COLUMN IF NOT EXISTS requirement TEXT;                            -- Requirement side of the relationship.
COMMENT ON TABLE step_requirements IS 'Many-to-many Step/Requirement semantics normalized into an ERB junction table.';
COMMENT ON COLUMN step_requirements.step_requirement_id IS 'Stored logical identifier for one StepRequirements row.';
COMMENT ON COLUMN step_requirements.step IS 'Step side of the relationship.';
COMMENT ON COLUMN step_requirements.requirement IS 'Requirement side of the relationship.';

-- ----------------------------------------------------------------------------
-- StepVerifications: Verification definitions attached to steps. Maps to pko:StepVerification and pko:SignalVerification.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS step_verifications (
  step_verification_id                TEXT                 PRIMARY KEY          -- Stored logical identifier for one StepVerifications row.
);
ALTER TABLE step_verifications ADD COLUMN IF NOT EXISTS step TEXT;                                  -- Step whose execution is verified; maps to pko:hasStepVerification.
ALTER TABLE step_verifications ADD COLUMN IF NOT EXISTS verification_kind TEXT;                     -- SignalVerification, ApprovalVerification, ProvenanceVerification, or another documented kind.
ALTER TABLE step_verifications ADD COLUMN IF NOT EXISTS signal_identifier TEXT;                     -- Signal or evidence key; maps to pko:signalIdentifier for signal verifications.
ALTER TABLE step_verifications ADD COLUMN IF NOT EXISTS expected_signal_value TEXT;                 -- Expected value; maps to pko:expectedSignalValue.
ALTER TABLE step_verifications ADD COLUMN IF NOT EXISTS instruction TEXT;                           -- How to verify the step.
ALTER TABLE step_verifications ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                     -- Exact PKO or extension class IRI.
COMMENT ON TABLE step_verifications IS 'Verification definitions attached to steps. Maps to pko:StepVerification and pko:SignalVerification.';
COMMENT ON COLUMN step_verifications.step_verification_id IS 'Stored logical identifier for one StepVerifications row.';
COMMENT ON COLUMN step_verifications.step IS 'Step whose execution is verified; maps to pko:hasStepVerification.';
COMMENT ON COLUMN step_verifications.verification_kind IS 'SignalVerification, ApprovalVerification, ProvenanceVerification, or another documented kind.';
COMMENT ON COLUMN step_verifications.signal_identifier IS 'Signal or evidence key; maps to pko:signalIdentifier for signal verifications.';
COMMENT ON COLUMN step_verifications.expected_signal_value IS 'Expected value; maps to pko:expectedSignalValue.';
COMMENT ON COLUMN step_verifications.instruction IS 'How to verify the step.';
COMMENT ON COLUMN step_verifications.semantic_type_iri IS 'Exact PKO or extension class IRI.';

-- ----------------------------------------------------------------------------
-- Rationales: First-class rationale statements explaining why procedural commitments and design decisions exist. Explicit ERB-PKO extension, represented as prov:Entity/dcat:Resource in projections.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS rationales (
  rationale_id                        TEXT                 PRIMARY KEY          -- Stored logical identifier for one Rationales row.
);
ALTER TABLE rationales ADD COLUMN IF NOT EXISTS procedure_version TEXT;                             -- Version justified by the rationale.
ALTER TABLE rationales ADD COLUMN IF NOT EXISTS step TEXT;                                          -- Optional step justified by the rationale.
ALTER TABLE rationales ADD COLUMN IF NOT EXISTS title TEXT;                                         -- Rationale title.
ALTER TABLE rationales ADD COLUMN IF NOT EXISTS statement TEXT;                                     -- Reasoned explanation.
ALTER TABLE rationales ADD COLUMN IF NOT EXISTS status TEXT;                                        -- Draft, Reviewed, Approved, or Superseded.
ALTER TABLE rationales ADD COLUMN IF NOT EXISTS authority_role TEXT;                                -- Role authorized to approve the rationale.
ALTER TABLE rationales ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                             -- Extension class IRI.
COMMENT ON TABLE rationales IS 'First-class rationale statements explaining why procedural commitments and design decisions exist. Explicit ERB-PKO extension, represented as prov:Entity/dcat:Resource in projections.';
COMMENT ON COLUMN rationales.rationale_id IS 'Stored logical identifier for one Rationales row.';
COMMENT ON COLUMN rationales.procedure_version IS 'Version justified by the rationale.';
COMMENT ON COLUMN rationales.step IS 'Optional step justified by the rationale.';
COMMENT ON COLUMN rationales.title IS 'Rationale title.';
COMMENT ON COLUMN rationales.statement IS 'Reasoned explanation.';
COMMENT ON COLUMN rationales.status IS 'Draft, Reviewed, Approved, or Superseded.';
COMMENT ON COLUMN rationales.authority_role IS 'Role authorized to approve the rationale.';
COMMENT ON COLUMN rationales.semantic_type_iri IS 'Extension class IRI.';

-- ----------------------------------------------------------------------------
-- Exceptions: Documented exceptions, fallbacks, and alternative handling. Aligns structurally with PKO fallback/alternative steps and requirements; the exception record itself is an ERB-PKO extension.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS exceptions (
  exception_id                        TEXT                 PRIMARY KEY          -- Stored logical identifier for one Exceptions row.
);
ALTER TABLE exceptions ADD COLUMN IF NOT EXISTS procedure_version TEXT;                             -- Procedure version containing the exception.
ALTER TABLE exceptions ADD COLUMN IF NOT EXISTS trigger_step TEXT;                                  -- Step at which the exception becomes relevant.
ALTER TABLE exceptions ADD COLUMN IF NOT EXISTS condition TEXT;                                     -- Exception condition.
ALTER TABLE exceptions ADD COLUMN IF NOT EXISTS handling TEXT;                                      -- Required handling and guardrails.
ALTER TABLE exceptions ADD COLUMN IF NOT EXISTS approval_role TEXT;                                 -- Role that approves use of the exception.
ALTER TABLE exceptions ADD COLUMN IF NOT EXISTS fallback_role TEXT;                                 -- Role or function that executes fallback handling.
ALTER TABLE exceptions ADD COLUMN IF NOT EXISTS status TEXT;                                        -- Active, Draft, Retired, or Superseded.
ALTER TABLE exceptions ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                             -- Extension class IRI.
COMMENT ON TABLE exceptions IS 'Documented exceptions, fallbacks, and alternative handling. Aligns structurally with PKO fallback/alternative steps and requirements; the exception record itself is an ERB-PKO extension.';
COMMENT ON COLUMN exceptions.exception_id IS 'Stored logical identifier for one Exceptions row.';
COMMENT ON COLUMN exceptions.procedure_version IS 'Procedure version containing the exception.';
COMMENT ON COLUMN exceptions.trigger_step IS 'Step at which the exception becomes relevant.';
COMMENT ON COLUMN exceptions.condition IS 'Exception condition.';
COMMENT ON COLUMN exceptions.handling IS 'Required handling and guardrails.';
COMMENT ON COLUMN exceptions.approval_role IS 'Role that approves use of the exception.';
COMMENT ON COLUMN exceptions.fallback_role IS 'Role or function that executes fallback handling.';
COMMENT ON COLUMN exceptions.status IS 'Active, Draft, Retired, or Superseded.';
COMMENT ON COLUMN exceptions.semantic_type_iri IS 'Extension class IRI.';

-- ----------------------------------------------------------------------------
