ALTER TABLE resources ADD COLUMN IF NOT EXISTS resource_kind TEXT;                                  -- Document, Dataset, API, Template, OperationalRecord, Image, Video, or another declared type.
ALTER TABLE resources ADD COLUMN IF NOT EXISTS external_uri TEXT;                                   -- Resolvable or organization-internal resource identifier.
ALTER TABLE resources ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ;                              -- Creation time; maps to dcterms:created.
ALTER TABLE resources ADD COLUMN IF NOT EXISTS modified_at TIMESTAMPTZ;                             -- Modification time; maps to dcterms:modified.
ALTER TABLE resources ADD COLUMN IF NOT EXISTS description TEXT;                                    -- Resource description; maps to dcterms:description.
ALTER TABLE resources ADD COLUMN IF NOT EXISTS approval_status TEXT;                                -- Approved, Draft, Deprecated, or Unvetted.
ALTER TABLE resources ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                              -- Exact semantic class IRI.
ALTER TABLE resources ADD COLUMN IF NOT EXISTS language TEXT;                                       -- Language (dct:language).
ALTER TABLE resources ADD COLUMN IF NOT EXISTS keywords TEXT;                                       -- Keywords (dcat:keyword).
ALTER TABLE resources ADD COLUMN IF NOT EXISTS format TEXT;                                         -- Media type (dct:format).
ALTER TABLE resources ADD COLUMN IF NOT EXISTS created_by_agent TEXT;                               -- Creator (dct:creator).
ALTER TABLE resources ADD COLUMN IF NOT EXISTS modified_by_agent TEXT;                              -- Last modifier (pko:wasModifiedBy).
ALTER TABLE resources ADD COLUMN IF NOT EXISTS extracted_from_resource TEXT;                        -- Resource this one was extracted from (pko:wasExtractedFrom).
ALTER TABLE resources ADD COLUMN IF NOT EXISTS artifact_type_concept TEXT;                          -- Artifact type from the controlled artifact-type scheme.
ALTER TABLE resources ADD COLUMN IF NOT EXISTS catalog_entry_for TEXT;                              -- The procedure this resource is the catalog entry of.
ALTER TABLE resources ADD COLUMN IF NOT EXISTS compliance_record_for TEXT;                          -- The procedure this document is kept as a compliance record for.
