COMMENT ON COLUMN resources.modified_at IS 'Modification time; maps to dcterms:modified.';
COMMENT ON COLUMN resources.description IS 'Resource description; maps to dcterms:description.';
COMMENT ON COLUMN resources.approval_status IS 'Approved, Draft, Deprecated, or Unvetted.';
COMMENT ON COLUMN resources.semantic_type_iri IS 'Exact semantic class IRI.';
COMMENT ON COLUMN resources.language IS 'Language (dct:language).';
COMMENT ON COLUMN resources.keywords IS 'Keywords (dcat:keyword).';
COMMENT ON COLUMN resources.format IS 'Media type (dct:format).';
COMMENT ON COLUMN resources.created_by_agent IS 'Creator (dct:creator).';
COMMENT ON COLUMN resources.modified_by_agent IS 'Last modifier (pko:wasModifiedBy).';
COMMENT ON COLUMN resources.extracted_from_resource IS 'Resource this one was extracted from (pko:wasExtractedFrom).';
COMMENT ON COLUMN resources.artifact_type_concept IS 'Artifact type from the controlled artifact-type scheme.';
COMMENT ON COLUMN resources.catalog_entry_for IS 'The procedure this resource is the catalog entry of.';
COMMENT ON COLUMN resources.compliance_record_for IS 'The procedure this document is kept as a compliance record for.';

-- ----------------------------------------------------------------------------
