  procedure_resource_id               TEXT                 PRIMARY KEY          -- Stored logical identifier for one ProcedureResources row.
);
ALTER TABLE procedure_resources ADD COLUMN IF NOT EXISTS procedure_version TEXT;                    -- Procedure version.
ALTER TABLE procedure_resources ADD COLUMN IF NOT EXISTS resource TEXT;                             -- Referenced or source resource.
ALTER TABLE procedure_resources ADD COLUMN IF NOT EXISTS relation TEXT;                             -- wasExtractedFrom, references, generated, used, or another declared relation.
COMMENT ON TABLE procedure_resources IS 'Links versioned procedures to supporting resources using PKO/dcterms provenance relations.';
COMMENT ON COLUMN procedure_resources.procedure_resource_id IS 'Stored logical identifier for one ProcedureResources row.';
COMMENT ON COLUMN procedure_resources.procedure_version IS 'Procedure version.';
COMMENT ON COLUMN procedure_resources.resource IS 'Referenced or source resource.';
COMMENT ON COLUMN procedure_resources.relation IS 'wasExtractedFrom, references, generated, used, or another declared relation.';

-- ----------------------------------------------------------------------------
-- ElicitationSessions: Structured knowledge-elicitation events involving practitioners and knowledge engineers. Explicit ERB-PKO extension, modeled as prov:Activity.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS elicitation_sessions (
  elicitation_session_id              TEXT                 PRIMARY KEY          -- Stored logical identifier for one ElicitationSessions row.
);
ALTER TABLE elicitation_sessions ADD COLUMN IF NOT EXISTS procedure_version TEXT;                   -- Procedure version whose knowledge was elicited.
ALTER TABLE elicitation_sessions ADD COLUMN IF NOT EXISTS method TEXT;                              -- The knowledge method this session used.
ALTER TABLE elicitation_sessions ADD COLUMN IF NOT EXISTS started_at TIMESTAMPTZ;                   -- Start time; maps to prov:startedAtTime.
ALTER TABLE elicitation_sessions ADD COLUMN IF NOT EXISTS ended_at TIMESTAMPTZ;                     -- End time; maps to prov:endedAtTime.
ALTER TABLE elicitation_sessions ADD COLUMN IF NOT EXISTS practitioner_agent TEXT;                  -- Domain practitioner providing knowledge.
ALTER TABLE elicitation_sessions ADD COLUMN IF NOT EXISTS facilitator_agent TEXT;                   -- Person facilitating elicitation.
ALTER TABLE elicitation_sessions ADD COLUMN IF NOT EXISTS summary TEXT;                             -- What was learned and captured.
ALTER TABLE elicitation_sessions ADD COLUMN IF NOT EXISTS status TEXT;                              -- Draft, Reviewed, Approved, or Rejected.
ALTER TABLE elicitation_sessions ADD COLUMN IF NOT EXISTS evaluation_context TEXT;                  -- The evaluation context this row's time-dependent witnesses are judged under.
ALTER TABLE elicitation_sessions ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                   -- Class IRI used in semantic projection.
ALTER TABLE elicitation_sessions ADD COLUMN IF NOT EXISTS observer_stance TEXT;                     -- For observation: NonParticipantObservation, Shadowing or LegitimatePeripheralParticipation.
ALTER TABLE elicitation_sessions ADD COLUMN IF NOT EXISTS setting TEXT;                             -- InSitu (where the work is done), Office or Remote.
ALTER TABLE elicitation_sessions ADD COLUMN IF NOT EXISTS recording_reference TEXT;                 -- The recording of the practitioner's work made during the session, when one was made.
ALTER TABLE elicitation_sessions ADD COLUMN IF NOT EXISTS practitioner_reviewed_at TIMESTAMPTZ;     -- When the practitioner reviewed the recording afterward to explain their reasoning.
COMMENT ON TABLE elicitation_sessions IS 'Structured knowledge-elicitation events involving practitioners and knowledge engineers. Explicit ERB-PKO extension, modeled as prov:Activity.';
COMMENT ON COLUMN elicitation_sessions.elicitation_session_id IS 'Stored logical identifier for one ElicitationSessions row.';
COMMENT ON COLUMN elicitation_sessions.procedure_version IS 'Procedure version whose knowledge was elicited.';
COMMENT ON COLUMN elicitation_sessions.method IS 'The knowledge method this session used.';
COMMENT ON COLUMN elicitation_sessions.started_at IS 'Start time; maps to prov:startedAtTime.';
COMMENT ON COLUMN elicitation_sessions.ended_at IS 'End time; maps to prov:endedAtTime.';
COMMENT ON COLUMN elicitation_sessions.practitioner_agent IS 'Domain practitioner providing knowledge.';
COMMENT ON COLUMN elicitation_sessions.facilitator_agent IS 'Person facilitating elicitation.';
COMMENT ON COLUMN elicitation_sessions.summary IS 'What was learned and captured.';
COMMENT ON COLUMN elicitation_sessions.status IS 'Draft, Reviewed, Approved, or Rejected.';
COMMENT ON COLUMN elicitation_sessions.evaluation_context IS 'The evaluation context this row''s time-dependent witnesses are judged under.';
COMMENT ON COLUMN elicitation_sessions.semantic_type_iri IS 'Class IRI used in semantic projection.';
COMMENT ON COLUMN elicitation_sessions.observer_stance IS 'For observation: NonParticipantObservation, Shadowing or LegitimatePeripheralParticipation.';
COMMENT ON COLUMN elicitation_sessions.setting IS 'InSitu (where the work is done), Office or Remote.';
COMMENT ON COLUMN elicitation_sessions.recording_reference IS 'The recording of the practitioner''s work made during the session, when one was made.';
COMMENT ON COLUMN elicitation_sessions.practitioner_reviewed_at IS 'When the practitioner reviewed the recording afterward to explain their reasoning.';

-- ----------------------------------------------------------------------------
-- KnowledgeFragments: Explicit records of tacit, implicit, explicit, and situated procedural knowledge. This is an ERB-PKO extension represented as provenance-bearing dcat:Resource instances.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS knowledge_fragments (
  knowledge_fragment_id               TEXT                 PRIMARY KEY          -- Stored logical identifier for one KnowledgeFragments row.
);
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS procedure_version TEXT;                    -- Procedure version informed by the fragment.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS step TEXT;                                 -- Optional step to which the fragment applies.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS knowledge_form TEXT;                       -- Tacit, Implicit, Explicit, SituatedJudgment, LessonLearned, or another declared form.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS statement TEXT;                            -- Captured knowledge statement.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS elicitation_session TEXT;                  -- Optional elicitation session that produced the fragment.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS source_agent TEXT;                         -- Practitioner or source agent.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS confidence TEXT;                           -- Low, Medium, or High confidence.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS valid_from TIMESTAMPTZ;                    -- Start of the fragment's valid-time interval.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS valid_to TIMESTAMPTZ;                      -- End of the fragment's valid-time interval.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS status TEXT;                               -- Draft, Reviewed, Approved, Rejected, or Superseded.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS owner_role TEXT;                           -- Role accountable for maintaining the fragment.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS evaluation_context TEXT;                   -- The evaluation context this row's time-dependent witnesses are judged under.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS last_reviewed_at TIMESTAMPTZ;              -- When this fragment was last actually reviewed and reaffirmed by its owning role. Null when it has never been reviewed since authoring. IsOverdueForReview infers recency from ValidFrom, which records when the claim became TRUE, not when anyone last looked at it. Those are different events, and the inference is deliberately left in place under its own name rather than silently rewritten to fall back on this column.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                    -- Extension class IRI.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS cognitive_basis TEXT;                      -- Intuition, PatternRecognition or Judgment for tacit knowledge; Articulated for knowledge stated outright.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS tacitness_degree INTEGER;                  -- Position on the tacit-to-explicit spectrum: 1 fully articulated to 5 not articulable.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS lost_in_translation TEXT;                  -- What the explicit statement fails to carry of the practice it was drawn from.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS encoded_as TEXT;                           -- HardRule, ConditionedGuidance, CueNarrative or Statement.
ALTER TABLE knowledge_fragments ADD COLUMN IF NOT EXISTS stated_conditions TEXT;                    -- The conditions under which the fragment holds, as captured.
COMMENT ON TABLE knowledge_fragments IS 'Explicit records of tacit, implicit, explicit, and situated procedural knowledge. This is an ERB-PKO extension represented as provenance-bearing dcat:Resource instances.';
COMMENT ON COLUMN knowledge_fragments.knowledge_fragment_id IS 'Stored logical identifier for one KnowledgeFragments row.';
COMMENT ON COLUMN knowledge_fragments.procedure_version IS 'Procedure version informed by the fragment.';
COMMENT ON COLUMN knowledge_fragments.step IS 'Optional step to which the fragment applies.';
COMMENT ON COLUMN knowledge_fragments.knowledge_form IS 'Tacit, Implicit, Explicit, SituatedJudgment, LessonLearned, or another declared form.';
COMMENT ON COLUMN knowledge_fragments.statement IS 'Captured knowledge statement.';
COMMENT ON COLUMN knowledge_fragments.elicitation_session IS 'Optional elicitation session that produced the fragment.';
COMMENT ON COLUMN knowledge_fragments.source_agent IS 'Practitioner or source agent.';
COMMENT ON COLUMN knowledge_fragments.confidence IS 'Low, Medium, or High confidence.';
COMMENT ON COLUMN knowledge_fragments.valid_from IS 'Start of the fragment''s valid-time interval.';
COMMENT ON COLUMN knowledge_fragments.valid_to IS 'End of the fragment''s valid-time interval.';
COMMENT ON COLUMN knowledge_fragments.status IS 'Draft, Reviewed, Approved, Rejected, or Superseded.';
COMMENT ON COLUMN knowledge_fragments.owner_role IS 'Role accountable for maintaining the fragment.';
COMMENT ON COLUMN knowledge_fragments.evaluation_context IS 'The evaluation context this row''s time-dependent witnesses are judged under.';
COMMENT ON COLUMN knowledge_fragments.last_reviewed_at IS 'When this fragment was last actually reviewed and reaffirmed by its owning role. Null when it has never been reviewed since authoring. IsOverdueForReview infers recency from ValidFrom, which records when the claim became TRUE, not when anyone last looked at it. Those are different events, and the inference is deliberately left in place under its own name rather than silently rewritten to fall back on this column.';
COMMENT ON COLUMN knowledge_fragments.semantic_type_iri IS 'Extension class IRI.';
COMMENT ON COLUMN knowledge_fragments.cognitive_basis IS 'Intuition, PatternRecognition or Judgment for tacit knowledge; Articulated for knowledge stated outright.';
COMMENT ON COLUMN knowledge_fragments.tacitness_degree IS 'Position on the tacit-to-explicit spectrum: 1 fully articulated to 5 not articulable.';
COMMENT ON COLUMN knowledge_fragments.lost_in_translation IS 'What the explicit statement fails to carry of the practice it was drawn from.';
COMMENT ON COLUMN knowledge_fragments.encoded_as IS 'HardRule, ConditionedGuidance, CueNarrative or Statement.';
COMMENT ON COLUMN knowledge_fragments.stated_conditions IS 'The conditions under which the fragment holds, as captured.';

-- ----------------------------------------------------------------------------
-- KnowledgeGaps: Known unknowns and missing procedural coverage. Explicit ERB-PKO extension used to govern scope and prevent silent incompleteness.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS knowledge_gaps (
  knowledge_gap_id                    TEXT                 PRIMARY KEY          -- Stored logical identifier for one KnowledgeGaps row.
);
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS procedure_version TEXT;                         -- Affected procedure version.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS step TEXT;                                      -- Affected step.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS statement TEXT;                                 -- What is not yet known or represented.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS severity TEXT;                                  -- Low, Medium, High, or Critical.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS blocking_kind TEXT;                             -- Blocking or NonBlocking.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS status TEXT;                                    -- Open, Investigating, Resolved, AcceptedRisk, or Closed.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS owner_role TEXT;                                -- Role responsible for resolving the gap.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS identified_at TIMESTAMPTZ;                      -- Time the gap was identified.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS resolution_plan TEXT;                           -- Resolution plan or final resolution.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS evaluation_context TEXT;                        -- The evaluation context this row's time-dependent witnesses are judged under.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                         -- Extension class IRI.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS gap_cause TEXT;                                 -- Gatekeeping, Sabotage, Undocumented or Unknown; blank when never classified.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS holder_declined_to_share BOOLEAN;               -- TRUE when an elicitation recorded the one person who knows declining to share it.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS siloed_within TEXT;                             -- The group the knowledge stays inside.
ALTER TABLE knowledge_gaps ADD COLUMN IF NOT EXISTS drawn_out_by_session TEXT;                      -- The session that drew the gatekept knowledge out.
