-- ----------------------------------------------------------------------------
-- ChangeRequests: Governed requests for semantic or operational change, anchored to a procedure version and authority. Explicit ERB-PKO extension.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS change_requests (
  change_request_id                   TEXT                 PRIMARY KEY          -- Stored logical identifier for one ChangeRequests row.
);
ALTER TABLE change_requests ADD COLUMN IF NOT EXISTS procedure_version TEXT;                        -- Procedure version affected.
ALTER TABLE change_requests ADD COLUMN IF NOT EXISTS title TEXT;                                    -- Change title.
ALTER TABLE change_requests ADD COLUMN IF NOT EXISTS change_kind TEXT;                              -- Defect, Enhancement, NewRequirement, DataOperation, or BreakingChange.
ALTER TABLE change_requests ADD COLUMN IF NOT EXISTS status TEXT;                                   -- Draft, UnderReview, Approved, Rejected, Implemented, or Closed.
ALTER TABLE change_requests ADD COLUMN IF NOT EXISTS requested_by_agent TEXT;                       -- Agent requesting the change.
ALTER TABLE change_requests ADD COLUMN IF NOT EXISTS authority_role TEXT;                           -- Role authorized to approve the change.
ALTER TABLE change_requests ADD COLUMN IF NOT EXISTS requested_at TIMESTAMPTZ;                      -- Request time.
ALTER TABLE change_requests ADD COLUMN IF NOT EXISTS decided_at TIMESTAMPTZ;                        -- Decision time.
ALTER TABLE change_requests ADD COLUMN IF NOT EXISTS impact_assessment TEXT;                        -- Expected effect on commitments, data, projections, and tests.
ALTER TABLE change_requests ADD COLUMN IF NOT EXISTS evaluation_context TEXT;                       -- The evaluation context this row's time-dependent witnesses are judged under.
ALTER TABLE change_requests ADD COLUMN IF NOT EXISTS implemented_at TIMESTAMPTZ;                    -- When the approved change was actually applied to the procedure version. Null until it lands. Distinct from DecidedAt, which records only that the authority ruled. Approval and implementation are separate events; conflating them is what left IsOpen with no terminal state.
