-- ----------------------------------------------------------------------------
-- MessageTemplates: Approved channel templates projected from the canonical rulebook without becoming a second source of policy meaning.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS message_templates (
  message_template_id                 TEXT                 PRIMARY KEY          -- Stored logical identifier for one MessageTemplates row.
);
ALTER TABLE message_templates ADD COLUMN IF NOT EXISTS communication_policy TEXT;                   -- Channel policy governing the template.
ALTER TABLE message_templates ADD COLUMN IF NOT EXISTS resource TEXT;                               -- Template resource.
ALTER TABLE message_templates ADD COLUMN IF NOT EXISTS subject_template TEXT;                       -- Subject template where supported.
ALTER TABLE message_templates ADD COLUMN IF NOT EXISTS body_template TEXT;                          -- Body template.
ALTER TABLE message_templates ADD COLUMN IF NOT EXISTS locale TEXT;                                 -- Locale or language tag.
ALTER TABLE message_templates ADD COLUMN IF NOT EXISTS status TEXT;                                 -- Draft, Approved, Retired, or Superseded.
ALTER TABLE message_templates ADD COLUMN IF NOT EXISTS current_body_hash TEXT;                      -- Digest of the template's current body text, maintained whenever the body is edited.
ALTER TABLE message_templates ADD COLUMN IF NOT EXISTS last_valid_approval TEXT;                    -- The TemplateApprovals id of the approval this template is currently sendable under. Deliberately a raw identifier, not a relationship: TemplateApprovals already points at MessageTemplates, so declaring an FK back would make the two tables mutually dependent and the rulebook is required to stay acyclic. The value is still resolved by INDEX/MATCH in LastApprovedBodyHash.
