-- ----------------------------------------------------------------------------
-- ReasonerRuns: One reasoner run over a grounding snapshot: consistency, materialization, budget and dropped axioms.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS reasoner_runs (
  reasoner_run_id                     TEXT                 PRIMARY KEY          -- Stored identifier.
);
ALTER TABLE reasoner_runs ADD COLUMN IF NOT EXISTS snapshot TEXT;                                   -- Snapshot reasoned over.
ALTER TABLE reasoner_runs ADD COLUMN IF NOT EXISTS reasoner_profile TEXT;                           -- OWL 2 RL, OWL 2 DL or RDFS.
ALTER TABLE reasoner_runs ADD COLUMN IF NOT EXISTS ran_at TIMESTAMPTZ;                              -- When run.
ALTER TABLE reasoner_runs ADD COLUMN IF NOT EXISTS materialized_at TIMESTAMPTZ;                     -- When entailments were written into the snapshot; blank if not.
ALTER TABLE reasoner_runs ADD COLUMN IF NOT EXISTS is_consistent BOOLEAN;                           -- Whether the reasoner found the snapshot consistent.
ALTER TABLE reasoner_runs ADD COLUMN IF NOT EXISTS inferred_triple_count INTEGER;                   -- Triples inferred.
ALTER TABLE reasoner_runs ADD COLUMN IF NOT EXISTS duration_seconds NUMERIC;                        -- Run time.
ALTER TABLE reasoner_runs ADD COLUMN IF NOT EXISTS time_budget_seconds NUMERIC;                     -- Time allowed before serving.
ALTER TABLE reasoner_runs ADD COLUMN IF NOT EXISTS dropped_axiom_count INTEGER;                     -- Axioms the profile could not express and dropped.
ALTER TABLE reasoner_runs ADD COLUMN IF NOT EXISTS schema_validation_passed BOOLEAN;                -- Whether the export passed plain schema (shape of the tables) validation.
ALTER TABLE reasoner_runs ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                          -- Semantic type IRI.
COMMENT ON TABLE reasoner_runs IS 'One reasoner run over a grounding snapshot: consistency, materialization, budget and dropped axioms.';
COMMENT ON COLUMN reasoner_runs.reasoner_run_id IS 'Stored identifier.';
COMMENT ON COLUMN reasoner_runs.snapshot IS 'Snapshot reasoned over.';
