-- ----------------------------------------------------------------------------
-- ModelCharters: Ownership charters: who stewards a governed model and who holds authority over it, with written responsibilities, for a period.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS model_charters (
  model_charter_id                    TEXT                 PRIMARY KEY          -- Stored identifier.
);
ALTER TABLE model_charters ADD COLUMN IF NOT EXISTS governed_model TEXT;                            -- Model chartered.
ALTER TABLE model_charters ADD COLUMN IF NOT EXISTS steward_role TEXT;                              -- Role responsible for the model's health.
ALTER TABLE model_charters ADD COLUMN IF NOT EXISTS authority_role TEXT;                            -- Role empowered to approve changes.
ALTER TABLE model_charters ADD COLUMN IF NOT EXISTS steward_responsibilities TEXT;                  -- The steward's written responsibilities.
ALTER TABLE model_charters ADD COLUMN IF NOT EXISTS authority_approval_scope TEXT;                  -- What the authority approves, stated.
ALTER TABLE model_charters ADD COLUMN IF NOT EXISTS charter_template TEXT;                          -- Corporate charter template this charter was drawn from, if any.
ALTER TABLE model_charters ADD COLUMN IF NOT EXISTS local_adaptation TEXT;                          -- How this organization fitted the template to its own procedures, systems and constraints.
ALTER TABLE model_charters ADD COLUMN IF NOT EXISTS valid_from TIMESTAMPTZ;                         -- Charter start.
ALTER TABLE model_charters ADD COLUMN IF NOT EXISTS valid_to TIMESTAMPTZ;                           -- Charter end.
ALTER TABLE model_charters ADD COLUMN IF NOT EXISTS supersedes_charter TEXT;                        -- Charter this one replaced.
