ALTER TABLE knowledge_holdings ADD COLUMN IF NOT EXISTS holder_agent TEXT;                          -- The person who holds it, when a person does.
ALTER TABLE knowledge_holdings ADD COLUMN IF NOT EXISTS statement TEXT;                             -- What is held.
