ALTER TABLE know_how_carriers ADD COLUMN IF NOT EXISTS organization TEXT;                           -- The organization whose know-how this is.
ALTER TABLE know_how_carriers ADD COLUMN IF NOT EXISTS procedure TEXT;                              -- The procedure the know-how serves.
ALTER TABLE know_how_carriers ADD COLUMN IF NOT EXISTS community_of_practice TEXT;                  -- The community in which the know-how circulates.
ALTER TABLE know_how_carriers ADD COLUMN IF NOT EXISTS carrier_kind TEXT;                           -- Person, Facility or System.
ALTER TABLE know_how_carriers ADD COLUMN IF NOT EXISTS holder_agent TEXT;                           -- The person who carries it, when the carrier is a person.
ALTER TABLE know_how_carriers ADD COLUMN IF NOT EXISTS holder_facility TEXT;                        -- The plant that carries it in its layout and equipment, when the carrier is a facility.
ALTER TABLE know_how_carriers ADD COLUMN IF NOT EXISTS know_how_kind TEXT;                          -- WhatFails, Diagnosis, Improvisation or Refinement: the kind of practitioner know-how.
ALTER TABLE know_how_carriers ADD COLUMN IF NOT EXISTS is_in_written_procedure BOOLEAN;             -- TRUE when the know-how is written into a procedure.
