ALTER TABLE know_how_carriers ADD COLUMN IF NOT EXISTS work_medium TEXT;                            -- Physical or Digital work.
ALTER TABLE know_how_carriers ADD COLUMN IF NOT EXISTS held_since TIMESTAMPTZ;                      -- When the carrier began to hold the know-how.
ALTER TABLE know_how_carriers ADD COLUMN IF NOT EXISTS builds_on_know_how TEXT;                     -- Know-how about a related component or system this know-how depends on.
ALTER TABLE know_how_carriers ADD COLUMN IF NOT EXISTS is_in_public_references BOOLEAN;             -- TRUE when the know-how can be found in public references.
ALTER TABLE know_how_carriers ADD COLUMN IF NOT EXISTS replacement_plan TEXT;                       -- How the organization plans to replace the know-how if lost: PublicReference, AiGeneration, Apprenticeship, or blank.
ALTER TABLE know_how_carriers ADD COLUMN IF NOT EXISTS evaluation_context TEXT;                     -- The instant the row is judged against.
ALTER TABLE know_how_carriers ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                      -- Semantic type IRI.
COMMENT ON TABLE know_how_carriers IS 'One piece of an organization''s process know-how and what carries it: a person, a facility or a system, with the community it belongs to, the forms it is held in, and how long it took to build.';
