ALTER TABLE knowledge_repository_entries ADD COLUMN IF NOT EXISTS author_agent TEXT;                -- Who wrote the entry.
ALTER TABLE knowledge_repository_entries ADD COLUMN IF NOT EXISTS source_expert TEXT;               -- Whose expertise the entry records.
