-- ----------------------------------------------------------------------------
-- CapabilityDeclines: When an organization's training-and-retention cycle began to decline at one stage (facility investment, engineer training, upkeep of how-to-make knowledge) and the decline of the stage before it.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS capability_declines (
  capability_decline_id               TEXT                 PRIMARY KEY          -- Stored identifier.
);
ALTER TABLE capability_declines ADD COLUMN IF NOT EXISTS organization TEXT;                         -- The organization.
ALTER TABLE capability_declines ADD COLUMN IF NOT EXISTS stage TEXT;                                -- FacilityInvestment, EngineerTraining or KnowHowUpkeep.
ALTER TABLE capability_declines ADD COLUMN IF NOT EXISTS decline_started_at TIMESTAMPTZ;            -- When the decline started.
ALTER TABLE capability_declines ADD COLUMN IF NOT EXISTS preceding_stage_decline TEXT;              -- The decline of the stage that feeds this one.
ALTER TABLE capability_declines ADD COLUMN IF NOT EXISTS evidence TEXT;                             -- What shows the decline.
ALTER TABLE capability_declines ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                    -- Semantic type IRI.
COMMENT ON TABLE capability_declines IS 'When an organization''s training-and-retention cycle began to decline at one stage (facility investment, engineer training, upkeep of how-to-make knowledge) and the decline of the stage before it.';
COMMENT ON COLUMN capability_declines.capability_decline_id IS 'Stored identifier.';
COMMENT ON COLUMN capability_declines.organization IS 'The organization.';
COMMENT ON COLUMN capability_declines.stage IS 'FacilityInvestment, EngineerTraining or KnowHowUpkeep.';
COMMENT ON COLUMN capability_declines.decline_started_at IS 'When the decline started.';
COMMENT ON COLUMN capability_declines.preceding_stage_decline IS 'The decline of the stage that feeds this one.';
COMMENT ON COLUMN capability_declines.evidence IS 'What shows the decline.';
COMMENT ON COLUMN capability_declines.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- KnowledgeTraces: One trace from a piece of organized knowledge (a process model, an activity definition or a constraint) to the collected material it rests on, with the role the material plays (origin, validation, extension, contradiction), how the knowledge was derived, and who confirmed it.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS knowledge_traces (
  knowledge_trace_id                  TEXT                 PRIMARY KEY          -- Stored identifier.
);
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS target_kind TEXT;                             -- ProcessModel, ActivityDefinition or Constraint.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS procedure_version TEXT;                       -- The process model the traced knowledge belongs to.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS step TEXT;                                    -- The activity definition traced, when the target is a step.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS requirement TEXT;                             -- The constraint traced, when the target is a requirement.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS source_material TEXT;                         -- The collected material the knowledge traces to.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS trace_role TEXT;                              -- Origin (knowledge was taken from it), Validates, Extends, or Contradicts.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS traced_aspect TEXT;                           -- What the source is cited for: Sequence, StepDescription, Workaround, ActualExecution or Constraint.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS source_statement TEXT;                        -- Paraphrase of what the source says about the target.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS derivation_route TEXT;                        -- How the knowledge was produced from the source.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS derived_by_agent TEXT;                        -- Who (or what) derived the knowledge from the source.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS validated_by_agent TEXT;                      -- Who confirmed the derived knowledge.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS validated_at TIMESTAMPTZ;                     -- When it was confirmed.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS source_stated_duration_minutes INTEGER;       -- Duration the source states for the traced step, when it states one.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS contradicted_document TEXT;                   -- For a contradiction: the document whose prescription practice departs from.
ALTER TABLE knowledge_traces ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                       -- Semantic type IRI.
COMMENT ON TABLE knowledge_traces IS 'One trace from a piece of organized knowledge (a process model, an activity definition or a constraint) to the collected material it rests on, with the role the material plays (origin, validation, extension, contradiction), how the knowledge was derived, and who confirmed it.';
COMMENT ON COLUMN knowledge_traces.knowledge_trace_id IS 'Stored identifier.';
COMMENT ON COLUMN knowledge_traces.target_kind IS 'ProcessModel, ActivityDefinition or Constraint.';
COMMENT ON COLUMN knowledge_traces.procedure_version IS 'The process model the traced knowledge belongs to.';
COMMENT ON COLUMN knowledge_traces.step IS 'The activity definition traced, when the target is a step.';
COMMENT ON COLUMN knowledge_traces.requirement IS 'The constraint traced, when the target is a requirement.';
COMMENT ON COLUMN knowledge_traces.source_material IS 'The collected material the knowledge traces to.';
COMMENT ON COLUMN knowledge_traces.trace_role IS 'Origin (knowledge was taken from it), Validates, Extends, or Contradicts.';
COMMENT ON COLUMN knowledge_traces.traced_aspect IS 'What the source is cited for: Sequence, StepDescription, Workaround, ActualExecution or Constraint.';
COMMENT ON COLUMN knowledge_traces.source_statement IS 'Paraphrase of what the source says about the target.';
COMMENT ON COLUMN knowledge_traces.derivation_route IS 'How the knowledge was produced from the source.';
COMMENT ON COLUMN knowledge_traces.derived_by_agent IS 'Who (or what) derived the knowledge from the source.';
COMMENT ON COLUMN knowledge_traces.validated_by_agent IS 'Who confirmed the derived knowledge.';
COMMENT ON COLUMN knowledge_traces.validated_at IS 'When it was confirmed.';
COMMENT ON COLUMN knowledge_traces.source_stated_duration_minutes IS 'Duration the source states for the traced step, when it states one.';
COMMENT ON COLUMN knowledge_traces.contradicted_document IS 'For a contradiction: the document whose prescription practice departs from.';
COMMENT ON COLUMN knowledge_traces.semantic_type_iri IS 'Semantic type IRI.';

-- ----------------------------------------------------------------------------
-- MinedFlowEdges: One step-to-step hand-off reconstructed from a system event log by a process-mining run: how many cases took it, how long cases waited before the next step, and whether it is kept as observed behavior or recorded as intended logic.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS mined_flow_edges (
  mined_flow_edge_id                  TEXT                 PRIMARY KEY          -- Stored identifier.
);
ALTER TABLE mined_flow_edges ADD COLUMN IF NOT EXISTS process_mining_run TEXT;                      -- The mining run that reconstructed the hand-off.
ALTER TABLE mined_flow_edges ADD COLUMN IF NOT EXISTS from_step TEXT;                               -- Step the cases left.
ALTER TABLE mined_flow_edges ADD COLUMN IF NOT EXISTS to_step TEXT;                                 -- Step the cases entered next.
ALTER TABLE mined_flow_edges ADD COLUMN IF NOT EXISTS observed_case_count INTEGER;                  -- Cases in the log that took this hand-off.
ALTER TABLE mined_flow_edges ADD COLUMN IF NOT EXISTS median_wait_minutes INTEGER;                  -- Median minutes between leaving FromStep and starting ToStep.
ALTER TABLE mined_flow_edges ADD COLUMN IF NOT EXISTS recorded_stance TEXT;                         -- Observed (kept as mined behavior) or Intended (recorded as intended process logic).
ALTER TABLE mined_flow_edges ADD COLUMN IF NOT EXISTS intent_decision_by TEXT;                      -- Who decided that mined behavior should become intended logic.
ALTER TABLE mined_flow_edges ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                       -- Semantic type IRI.
COMMENT ON TABLE mined_flow_edges IS 'One step-to-step hand-off reconstructed from a system event log by a process-mining run: how many cases took it, how long cases waited before the next step, and whether it is kept as observed behavior or recorded as intended logic.';
COMMENT ON COLUMN mined_flow_edges.mined_flow_edge_id IS 'Stored identifier.';
COMMENT ON COLUMN mined_flow_edges.process_mining_run IS 'The mining run that reconstructed the hand-off.';
COMMENT ON COLUMN mined_flow_edges.from_step IS 'Step the cases left.';
COMMENT ON COLUMN mined_flow_edges.to_step IS 'Step the cases entered next.';
COMMENT ON COLUMN mined_flow_edges.observed_case_count IS 'Cases in the log that took this hand-off.';
COMMENT ON COLUMN mined_flow_edges.median_wait_minutes IS 'Median minutes between leaving FromStep and starting ToStep.';
COMMENT ON COLUMN mined_flow_edges.recorded_stance IS 'Observed (kept as mined behavior) or Intended (recorded as intended process logic).';
COMMENT ON COLUMN mined_flow_edges.intent_decision_by IS 'Who decided that mined behavior should become intended logic.';
COMMENT ON COLUMN mined_flow_edges.semantic_type_iri IS 'Semantic type IRI.';

