-- ----------------------------------------------------------------------------
-- StakeholderPerspectives: One stakeholder's view of how a step should be performed, kept with the collected material it comes from and the perspective it conflicts with, rather than merged into a single agreed version.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS stakeholder_perspectives (
  stakeholder_perspective_id          TEXT                 PRIMARY KEY          -- Stored identifier.
);
ALTER TABLE stakeholder_perspectives ADD COLUMN IF NOT EXISTS procedure_version TEXT;               -- The process model the view is about.
ALTER TABLE stakeholder_perspectives ADD COLUMN IF NOT EXISTS step TEXT;                            -- The step the view is about.
