ALTER TABLE stakeholder_perspectives ADD COLUMN IF NOT EXISTS position TEXT;                        -- The view, paraphrased.
ALTER TABLE stakeholder_perspectives ADD COLUMN IF NOT EXISTS source_material TEXT;                 -- The collected material the view comes from.
ALTER TABLE stakeholder_perspectives ADD COLUMN IF NOT EXISTS conflicts_with_perspective TEXT;      -- The perspective this one conflicts with.
ALTER TABLE stakeholder_perspectives ADD COLUMN IF NOT EXISTS disposition TEXT;                     -- Retained (kept alongside the other views) or OverriddenByConsensus.
ALTER TABLE stakeholder_perspectives ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;               -- Semantic type IRI.
COMMENT ON TABLE stakeholder_perspectives IS 'One stakeholder''s view of how a step should be performed, kept with the collected material it comes from and the perspective it conflicts with, rather than merged into a single agreed version.';
COMMENT ON COLUMN stakeholder_perspectives.stakeholder_perspective_id IS 'Stored identifier.';
COMMENT ON COLUMN stakeholder_perspectives.procedure_version IS 'The process model the view is about.';
COMMENT ON COLUMN stakeholder_perspectives.step IS 'The step the view is about.';
COMMENT ON COLUMN stakeholder_perspectives.holder_role IS 'The role whose view this is.';
COMMENT ON COLUMN stakeholder_perspectives.position IS 'The view, paraphrased.';
COMMENT ON COLUMN stakeholder_perspectives.source_material IS 'The collected material the view comes from.';
COMMENT ON COLUMN stakeholder_perspectives.conflicts_with_perspective IS 'The perspective this one conflicts with.';
COMMENT ON COLUMN stakeholder_perspectives.disposition IS 'Retained (kept alongside the other views) or OverriddenByConsensus.';
COMMENT ON COLUMN stakeholder_perspectives.semantic_type_iri IS 'Semantic type IRI.';

