-- ----------------------------------------------------------------------------
-- ArtifactHandoffs: One artifact passing from the step that produces it to a step that consumes it, asserted per declared input variable. The edge table the upgrade blast radius is traversed over.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS artifact_handoffs (
  artifact_handoff_id                 TEXT                 PRIMARY KEY          -- Stored identifier.
);
ALTER TABLE artifact_handoffs ADD COLUMN IF NOT EXISTS step_variable TEXT;                          -- The consuming step's input variable this hand-off feeds.
