ALTER TABLE artifact_handoffs ADD COLUMN IF NOT EXISTS to_step TEXT;                                -- Step that consumes it.
ALTER TABLE artifact_handoffs ADD COLUMN IF NOT EXISTS semantic_type_iri TEXT;                      -- Semantic type IRI.
COMMENT ON TABLE artifact_handoffs IS 'One artifact passing from the step that produces it to a step that consumes it, asserted per declared input variable. The edge table the upgrade blast radius is traversed over.';
COMMENT ON COLUMN artifact_handoffs.artifact_handoff_id IS 'Stored identifier.';
COMMENT ON COLUMN artifact_handoffs.step_variable IS 'The consuming step''s input variable this hand-off feeds.';
