  SELECT ((COALESCE(COALESCE((SELECT NULLIF(agent_kind, '') FROM agents WHERE agent_id = p_agent_id), '') = 'AIAgent', FALSE) AND COALESCE(COALESCE((calc_agents_answer_count(p_agent_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_agents_search_event_count(p_agent_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_agents_accountability_assertion_count
-- Field: Agents.AccountabilityAssertionCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_agents_accountability_assertion_count(p_agent_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM snapshot_assertions WHERE about_agent = (SELECT NULLIF(agent_id, '') FROM agents WHERE agent_id = p_agent_id) AND is_inferred = FALSE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_agents_inferred_category_count
-- Field: Agents.InferredCategoryCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_agents_inferred_category_count(p_agent_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM snapshot_assertions WHERE about_agent = (SELECT NULLIF(agent_id, '') FROM agents WHERE agent_id = p_agent_id) AND is_inferred = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_agents_category_not_available_as_inference
-- Field: Agents.CategoryNotAvailableAsInference
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_agents_category_not_available_as_inference(p_agent_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_agents_accountability_assertion_count(p_agent_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_agents_inferred_category_count(p_agent_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_agents_is_unclassified_agent
-- Field: Agents.IsUnclassifiedAgent
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_agents_is_unclassified_agent(p_agent_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(agent_kind, '') FROM agents WHERE agent_id = p_agent_id), '') <> 'Human', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(agent_kind, '') FROM agents WHERE agent_id = p_agent_id), '') <> 'AIAgent', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(agent_kind, '') FROM agents WHERE agent_id = p_agent_id), '') <> 'AutomatedPipeline', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(agent_kind, '') FROM agents WHERE agent_id = p_agent_id), '') <> 'Organization', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_agents_is_ai_agent_without_model_version
-- Field: Agents.IsAiAgentWithoutModelVersion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_agents_is_ai_agent_without_model_version(p_agent_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(agent_kind, '') FROM agents WHERE agent_id = p_agent_id), '') = 'AIAgent', FALSE) AND COALESCE((SELECT NULLIF(version_or_employment_key, '') FROM agents WHERE agent_id = p_agent_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_agents_attributed_artifact_count
-- Field: Agents.AttributedArtifactCount
