RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(agent_kind, '') FROM agents WHERE agent_id = p_agent_id), '') = 'AIAgent', FALSE) AND COALESCE(COALESCE((calc_agents_registry_version_match_count(p_agent_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_agents_current_accountable_human_count
