-- calc_agents_is_ai_agent_without_accountable_human
-- Field: Agents.IsAiAgentWithoutAccountableHuman
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_agents_is_ai_agent_without_accountable_human(p_agent_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(agent_kind, '') FROM agents WHERE agent_id = p_agent_id), '') = 'AIAgent', FALSE) AND COALESCE(COALESCE((calc_agents_count_of_current_role_assignments(p_agent_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_agents_current_accountable_human_count(p_agent_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

