-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_agents_is_unrewarded_sharer(p_agent_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_agents_transfers_given_count(p_agent_id))::NUMERIC, 0) >= 2, FALSE) AND COALESCE(COALESCE((calc_agents_recognition_count(p_agent_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

