-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_agents_artifact_blast_radius_step_count(p_agent_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE((SELECT NULLIF(agent_kind, '') FROM agents WHERE agent_id = p_agent_id), '') = 'AIAgent' THEN (calc_agents_downstream_of_held_steps_count(p_agent_id))::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

