-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_role_assignments_has_authorizing_change_request(p_role_assignment_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(authorizing_change_request, '') FROM role_assignments WHERE role_assignment_id = p_role_assignment_id) IS NOT NULL)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_role_assignments_is_unauthorized_enforcement_agent
-- Field: RoleAssignments.IsUnauthorizedEnforcementAgent
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_role_assignments_is_unauthorized_enforcement_agent(p_role_assignment_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT is_enforcement_role FROM role_assignments WHERE role_assignment_id = p_role_assignment_id), FALSE), FALSE) AND COALESCE(calc_role_assignments_is_unauthorized_non_human_assignment(p_role_assignment_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_role_assignments_governance_evidence_count
-- Field: RoleAssignments.GovernanceEvidenceCount
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_role_assignments_governance_evidence_count(p_role_assignment_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN calc_role_assignments_has_approving_authority(p_role_assignment_id) THEN (1)::text ELSE (0)::text END) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN calc_role_assignments_has_authorizing_change_request(p_role_assignment_id) THEN (1)::text ELSE (0)::text END) AS v) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_role_assignments_unauthorized_enforcement_role_key
-- Field: RoleAssignments.UnauthorizedEnforcementRoleKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_role_assignments_unauthorized_enforcement_role_key(p_role_assignment_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_role_assignments_is_unauthorized_non_human_assignment(p_role_assignment_id) THEN ((SELECT NULLIF(role, '') FROM role_assignments WHERE role_assignment_id = p_role_assignment_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_role_assignments_is_scoped_to_retired_version
-- Field: RoleAssignments.IsScopedToRetiredVersion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_role_assignments_is_scoped_to_retired_version(p_role_assignment_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_role_assignments_scoped_version_status(p_role_assignment_id) AS val) SELECT ((COALESCE(calc_role_assignments_is_current(p_role_assignment_id), FALSE) AND COALESCE((COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'Deprecated', FALSE) OR COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'Archived', FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_role_assignments_predecessor_lacks_validity_end
-- Field: RoleAssignments.PredecessorLacksValidityEnd
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_role_assignments_predecessor_lacks_validity_end(p_role_assignment_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(supersedes_assignment, '') FROM role_assignments WHERE role_assignment_id = p_role_assignment_id) IS NOT NULL, FALSE) AND COALESCE(calc_role_assignments_predecessor_valid_to(p_role_assignment_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_role_assignments_agent_role_pair_key
-- Field: RoleAssignments.AgentRolePairKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_role_assignments_agent_role_pair_key(p_role_assignment_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(agent, '') FROM role_assignments WHERE role_assignment_id = p_role_assignment_id), '|', (SELECT NULLIF(role, '') FROM role_assignments WHERE role_assignment_id = p_role_assignment_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_role_assignments_is_open_ended
-- Field: RoleAssignments.IsOpenEnded
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_role_assignments_is_open_ended(p_role_assignment_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT valid_to::timestamptz FROM role_assignments WHERE role_assignment_id = p_role_assignment_id) IS NULL)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_role_assignments_receives_approval_notices_now
-- Field: RoleAssignments.ReceivesApprovalNoticesNow
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_role_assignments_receives_approval_notices_now(p_role_assignment_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_role_assignments_covers_now(p_role_assignment_id), FALSE) AND COALESCE(COALESCE((calc_role_assignments_role_approval_step_count(p_role_assignment_id))::NUMERIC, 0) > 0, FALSE)));
$$ LANGUAGE sql STABLE;

