-- calc_communities_of_practice_has_own_vocabulary_and_norms
-- Field: CommunitiesOfPractice.HasOwnVocabularyAndNorms
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_communities_of_practice_has_own_vocabulary_and_norms(p_community_of_practice_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(own_vocabulary, '') FROM communities_of_practice WHERE community_of_practice_id = p_community_of_practice_id) IS NOT NULL, FALSE) AND COALESCE((SELECT NULLIF(norms, '') FROM communities_of_practice WHERE community_of_practice_id = p_community_of_practice_id) IS NOT NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_communities_of_practice_sharing_event_count
-- Field: CommunitiesOfPractice.SharingEventCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_communities_of_practice_sharing_event_count(p_community_of_practice_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM knowledge_transfers WHERE community_of_practice = (SELECT NULLIF(community_of_practice_id, '') FROM communities_of_practice WHERE community_of_practice_id = p_community_of_practice_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_communities_of_practice_is_mandated_without_sharing_norm
-- Field: CommunitiesOfPractice.IsMandatedWithoutSharingNorm
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_communities_of_practice_is_mandated_without_sharing_norm(p_community_of_practice_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(origin, '') FROM communities_of_practice WHERE community_of_practice_id = p_community_of_practice_id) IS NOT NULL, FALSE) AND COALESCE(COALESCE((SELECT NULLIF(origin, '') FROM communities_of_practice WHERE community_of_practice_id = p_community_of_practice_id), '') <> 'Grassroots', FALSE) AND COALESCE(COALESCE((calc_communities_of_practice_sharing_event_count(p_community_of_practice_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_communities_of_practice_interconnected_know_how_count
-- Field: CommunitiesOfPractice.InterconnectedKnowHowCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_communities_of_practice_interconnected_know_how_count(p_community_of_practice_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM know_how_carriers WHERE community_of_practice = (SELECT NULLIF(community_of_practice_id, '') FROM communities_of_practice WHERE community_of_practice_id = p_community_of_practice_id) AND calc_know_how_carriers_builds_on_same_community_know_how(know_how_carrier_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_communities_of_practice_physical_know_how_count
-- Field: CommunitiesOfPractice.PhysicalKnowHowCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_communities_of_practice_physical_know_how_count(p_community_of_practice_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM know_how_carriers WHERE community_of_practice = (SELECT NULLIF(community_of_practice_id, '') FROM communities_of_practice WHERE community_of_practice_id = p_community_of_practice_id) AND work_medium = 'Physical'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_communities_of_practice_digital_know_how_count
-- Field: CommunitiesOfPractice.DigitalKnowHowCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_communities_of_practice_digital_know_how_count(p_community_of_practice_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM know_how_carriers WHERE community_of_practice = (SELECT NULLIF(community_of_practice_id, '') FROM communities_of_practice WHERE community_of_practice_id = p_community_of_practice_id) AND work_medium = 'Digital'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_communities_of_practice_person_carried_know_how_count
-- Field: CommunitiesOfPractice.PersonCarriedKnowHowCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_communities_of_practice_person_carried_know_how_count(p_community_of_practice_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM know_how_carriers WHERE community_of_practice = (SELECT NULLIF(community_of_practice_id, '') FROM communities_of_practice WHERE community_of_practice_id = p_community_of_practice_id) AND carrier_kind = 'Person'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_communities_of_practice_spans_physical_and_digital_with_hu
-- Field: CommunitiesOfPractice.SpansPhysicalAndDigitalWithHumans
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_communities_of_practice_spans_physical_and_digital_with_hu(p_community_of_practice_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_communities_of_practice_physical_know_how_count(p_community_of_practice_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_communities_of_practice_digital_know_how_count(p_community_of_practice_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_communities_of_practice_person_carried_know_how_count(p_community_of_practice_id))::NUMERIC, 0) > 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_communities_of_practice_external_member_count
-- Field: CommunitiesOfPractice.ExternalMemberCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_communities_of_practice_external_member_count(p_community_of_practice_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM community_memberships WHERE community_of_practice = (SELECT NULLIF(community_of_practice_id, '') FROM communities_of_practice WHERE community_of_practice_id = p_community_of_practice_id) AND calc_community_memberships_is_external_member(community_membership_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_communities_of_practice_specialist_member_count
-- Field: CommunitiesOfPractice.SpecialistMemberCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_communities_of_practice_specialist_member_count(p_community_of_practice_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM community_memberships WHERE community_of_practice = (SELECT NULLIF(community_of_practice_id, '') FROM communities_of_practice WHERE community_of_practice_id = p_community_of_practice_id) AND is_specialist = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_communities_of_practice_employer_move_count
-- Field: CommunitiesOfPractice.EmployerMoveCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_communities_of_practice_employer_move_count(p_community_of_practice_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM knowledge_transfers WHERE community_of_practice = (SELECT NULLIF(community_of_practice_id, '') FROM communities_of_practice WHERE community_of_practice_id = p_community_of_practice_id) AND channel = 'EmployerChange'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_communities_of_practice_is_cross_firm_practice_cluster
-- Field: CommunitiesOfPractice.IsCrossFirmPracticeCluster
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_communities_of_practice_is_cross_firm_practice_cluster(p_community_of_practice_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_communities_of_practice_external_member_count(p_community_of_practice_id))::NUMERIC, 0) >= 2, FALSE) AND COALESCE(COALESCE((calc_communities_of_practice_employer_move_count(p_community_of_practice_id))::NUMERIC, 0) >= 1, FALSE) AND COALESCE(COALESCE((calc_communities_of_practice_specialist_member_count(p_community_of_practice_id))::NUMERIC, 0) >= 1, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_communities_of_practice_recent_apprenticeship_count
-- Field: CommunitiesOfPractice.RecentApprenticeshipCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_communities_of_practice_recent_apprenticeship_count(p_community_of_practice_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM mentorships WHERE community_of_practice = (SELECT NULLIF(community_of_practice_id, '') FROM communities_of_practice WHERE community_of_practice_id = p_community_of_practice_id) AND calc_mentorships_is_recent_apprenticeship(mentorship_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_communities_of_practice_is_circulation_ending_for_lack_of_
-- Field: CommunitiesOfPractice.IsCirculationEndingForLackOfApprentices
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_communities_of_practice_is_circulation_ending_for_lack_of_(p_community_of_practice_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_communities_of_practice_employer_move_count(p_community_of_practice_id))::NUMERIC, 0) >= 1, FALSE) AND COALESCE(COALESCE(((SELECT open_apprenticeship_places FROM communities_of_practice WHERE community_of_practice_id = p_community_of_practice_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_communities_of_practice_recent_apprenticeship_count(p_community_of_practice_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_communities_of_practice_ambient_absorption_count
-- Field: CommunitiesOfPractice.AmbientAbsorptionCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_communities_of_practice_ambient_absorption_count(p_community_of_practice_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM knowledge_transfers WHERE community_of_practice = (SELECT NULLIF(community_of_practice_id, '') FROM communities_of_practice WHERE community_of_practice_id = p_community_of_practice_id) AND calc_knowledge_transfers_is_ambient_absorption_by_non_practitio(knowledge_transfer_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_communities_of_practice_has_ambient_trade_know_how
-- Field: CommunitiesOfPractice.HasAmbientTradeKnowHow
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_communities_of_practice_has_ambient_trade_know_how(p_community_of_practice_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT is_colocated_trade FROM communities_of_practice WHERE community_of_practice_id = p_community_of_practice_id), FALSE), FALSE) AND COALESCE(COALESCE((calc_communities_of_practice_ambient_absorption_count(p_community_of_practice_id))::NUMERIC, 0) >= 1, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_mentorships_as_of_instant
