-- calc_procedure_versions_uses_ai_in_one_direction_only
-- Field: ProcedureVersions.UsesAiInOneDirectionOnly
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_procedure_versions_uses_ai_in_one_direction_only(p_procedure_version_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_procedure_versions_ai_contribution_count(p_procedure_version_id) AS val), __erb_dedup_v2 AS (SELECT calc_procedure_versions_ai_consumption_count(p_procedure_version_id) AS val) SELECT ((COALESCE((COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v2))::NUMERIC, 0) = 0, FALSE)), FALSE) OR COALESCE((COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) = 0, FALSE) AND COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v2))::NUMERIC, 0) > 0, FALSE)), FALSE)));
$$ LANGUAGE sql STABLE;

