-- calc_resources_is_stale_extraction
-- Field: Resources.IsStaleExtraction
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_resources_is_stale_extraction(p_resource_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(extracted_from_resource, '') FROM resources WHERE resource_id = p_resource_id) IS NOT NULL, FALSE) AND COALESCE(COALESCE((calc_resources_source_modified_at(p_resource_id) > (SELECT modified_at::timestamptz FROM resources WHERE resource_id = p_resource_id)), FALSE), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_resources_referencing_step_count
-- Field: Resources.ReferencingStepCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_resources_referencing_step_count(p_resource_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM step_resources WHERE resource = (SELECT NULLIF(resource_id, '') FROM resources WHERE resource_id = p_resource_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_resources_referencing_version_count
-- Field: Resources.ReferencingVersionCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_resources_referencing_version_count(p_resource_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM procedure_resources WHERE resource = (SELECT NULLIF(resource_id, '') FROM resources WHERE resource_id = p_resource_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_resources_is_unused_resource
-- Field: Resources.IsUnusedResource
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_resources_is_unused_resource(p_resource_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_resources_referencing_step_count(p_resource_id))::NUMERIC, 0) = 0, FALSE) AND COALESCE(COALESCE((calc_resources_referencing_version_count(p_resource_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_resources_is_content_without_organization
-- Field: Resources.IsContentWithoutOrganization
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_resources_is_content_without_organization(p_resource_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(description, '') FROM resources WHERE resource_id = p_resource_id) IS NOT NULL, FALSE) AND COALESCE((COALESCE((SELECT NULLIF(artifact_type_concept, '') FROM resources WHERE resource_id = p_resource_id) IS NULL, FALSE) OR COALESCE((SELECT NULLIF(keywords, '') FROM resources WHERE resource_id = p_resource_id) IS NULL, FALSE) OR COALESCE(COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_resources_referencing_step_count(p_resource_id)) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_resources_referencing_version_count(p_resource_id)) AS v) __safe_numeric), 0)))::NUMERIC, 0) = 0, FALSE)), FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_resources_trailing_practice_count
-- Field: Resources.TrailingPracticeCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_resources_trailing_practice_count(p_resource_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM knowledge_traces WHERE contradicted_document = (SELECT NULLIF(resource_id, '') FROM resources WHERE resource_id = p_resource_id) AND calc_knowledge_traces_is_document_trailing_practice(knowledge_trace_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_resources_is_behind_current_practice
-- Field: Resources.IsBehindCurrentPractice
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_resources_is_behind_current_practice(p_resource_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_resources_trailing_practice_count(p_resource_id))::NUMERIC, 0) > 0)::boolean;
$$ LANGUAGE sql STABLE;

