CREATE OR REPLACE FUNCTION calc_elicitation_sessions_facilitator_knowledge_engineer_role_c(p_elicitation_session_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM roles WHERE current_agent = (SELECT NULLIF(facilitator_agent, '') FROM elicitation_sessions WHERE elicitation_session_id = p_elicitation_session_id) AND role_id = 'knowledge-engineer'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_elicitation_sessions_facilitator_is_knowledge_engineer
