CREATE OR REPLACE FUNCTION calc_knowledge_fragments_rests_on_single_data_point(p_knowledge_fragment_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(status, '') FROM knowledge_fragments WHERE knowledge_fragment_id = p_knowledge_fragment_id), '') = 'Approved', FALSE) AND COALESCE(COALESCE((calc_knowledge_fragments_corroboration_count(p_knowledge_fragment_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_as_of_instant
