CREATE OR REPLACE FUNCTION calc_step_executions_is_ungoverned_divergence(p_step_execution_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((COALESCE(calc_step_executions_has_deviation(p_step_execution_id), FALSE) OR COALESCE(calc_step_executions_is_late(p_step_execution_id), FALSE) OR COALESCE(calc_step_executions_proceeded_past_blocking_control(p_step_execution_id), FALSE)), FALSE) AND COALESCE(NOT (COALESCE(calc_step_executions_has_governing_instrument(p_step_execution_id), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_step_executions_ungoverned_divergence_execution_key
-- Field: StepExecutions.UngovernedDivergenceExecutionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_step_executions_ungoverned_divergence_execution_key(p_step_execution_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_step_executions_is_ungoverned_divergence(p_step_execution_id) THEN ((SELECT NULLIF(procedure_execution, '') FROM step_executions WHERE step_execution_id = p_step_execution_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_step_executions_self_attested_approval_execution_key
-- Field: StepExecutions.SelfAttestedApprovalExecutionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_step_executions_self_attested_approval_execution_key(p_step_execution_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_step_executions_approval_rests_on_self_attestation(p_step_execution_id) THEN ((SELECT NULLIF(procedure_execution, '') FROM step_executions WHERE step_execution_id = p_step_execution_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_step_executions_specified_transition_from_previous_count
-- Field: StepExecutions.SpecifiedTransitionFromPreviousCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_step_executions_specified_transition_from_previous_count(p_step_execution_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM step_transitions WHERE from_step = calc_step_executions_previous_executed_step(p_step_execution_id) AND to_step = (SELECT NULLIF(step, '') FROM step_executions WHERE step_execution_id = p_step_execution_id)))::integer;
