-- calc_step_executions_is_out_of_specified_order
-- Field: StepExecutions.IsOutOfSpecifiedOrder
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_step_executions_is_out_of_specified_order(p_step_execution_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(previous_step_execution, '') FROM step_executions WHERE step_execution_id = p_step_execution_id) IS NOT NULL, FALSE) AND COALESCE(COALESCE((calc_step_executions_specified_transition_from_previous_count(p_step_execution_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_step_executions_executes_step_of_other_version
-- Field: StepExecutions.ExecutesStepOfOtherVersion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_step_executions_executes_step_of_other_version(p_step_execution_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE(calc_step_executions_version_of_step(p_step_execution_id), '') <> COALESCE(calc_step_executions_execution_version(p_step_execution_id), ''))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_step_executions_repetition_count
-- Field: StepExecutions.RepetitionCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_step_executions_repetition_count(p_step_execution_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM step_executions WHERE step = (SELECT NULLIF(step, '') FROM step_executions WHERE step_execution_id = p_step_execution_id) AND procedure_execution = (SELECT NULLIF(procedure_execution, '') FROM step_executions WHERE step_execution_id = p_step_execution_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_step_executions_exceeds_max_repetitions
-- Field: StepExecutions.ExceedsMaxRepetitions
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_step_executions_exceeds_max_repetitions(p_step_execution_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_step_executions_step_max_repetitions(p_step_execution_id) AS val) SELECT ((COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE(calc_step_executions_repetition_count(p_step_execution_id), 0) > COALESCE((SELECT val FROM __erb_dedup_v1), 0), FALSE)));
$$ LANGUAGE sql STABLE;

