-- calc_message_templates_name
-- Field: MessageTemplates.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_message_templates_name(p_message_template_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(communication_policy, '') FROM message_templates WHERE message_template_id = p_message_template_id), ' / ', (SELECT NULLIF(locale, '') FROM message_templates WHERE message_template_id = p_message_template_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_message_templates_body_template_length
-- Field: MessageTemplates.BodyTemplateLength
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_message_templates_body_template_length(p_message_template_id TEXT)
RETURNS INTEGER AS $$
  SELECT (LENGTH((SELECT NULLIF(body_template, '') FROM message_templates WHERE message_template_id = p_message_template_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_message_templates_is_template_over_length
-- Field: MessageTemplates.IsTemplateOverLength
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_message_templates_is_template_over_length(p_message_template_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE(calc_message_templates_body_template_length(p_message_template_id), 0) > COALESCE(calc_message_templates_policy_max_message_length(p_message_template_id), 0))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_message_templates_valid_approval_count
-- Field: MessageTemplates.ValidApprovalCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_message_templates_valid_approval_count(p_message_template_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM template_approvals WHERE calc_template_approvals_valid_approval_template_key(template_approval_id) = (SELECT NULLIF(message_template_id, '') FROM message_templates WHERE message_template_id = p_message_template_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_message_templates_has_valid_approval
-- Field: MessageTemplates.HasValidApproval
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_message_templates_has_valid_approval(p_message_template_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_message_templates_valid_approval_count(p_message_template_id))::NUMERIC, 0) > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_message_templates_is_claiming_unbacked_approval
-- Field: MessageTemplates.IsClaimingUnbackedApproval
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_message_templates_is_claiming_unbacked_approval(p_message_template_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(status, '') FROM message_templates WHERE message_template_id = p_message_template_id), '') = 'Approved', FALSE) AND COALESCE(NOT (COALESCE(calc_message_templates_has_valid_approval(p_message_template_id), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_message_templates_has_body_drifted
-- Field: MessageTemplates.HasBodyDrifted
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_message_templates_has_body_drifted(p_message_template_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_message_templates_last_approved_body_hash(p_message_template_id) AS val) SELECT ((COALESCE((SELECT val FROM __erb_dedup_v1) IS NOT NULL, FALSE) AND COALESCE(COALESCE((SELECT NULLIF(current_body_hash, '') FROM message_templates WHERE message_template_id = p_message_template_id), '') <> COALESCE((SELECT val FROM __erb_dedup_v1), ''), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_message_templates_is_sendable_under_approval
-- Field: MessageTemplates.IsSendableUnderApproval
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_message_templates_is_sendable_under_approval(p_message_template_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(status, '') FROM message_templates WHERE message_template_id = p_message_template_id), '') = 'Approved', FALSE) AND COALESCE((COALESCE(calc_message_templates_has_valid_approval(p_message_template_id), FALSE) AND COALESCE(NOT (COALESCE(calc_message_templates_has_body_drifted(p_message_template_id), FALSE)), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_message_templates_drifted_send_count
-- Field: MessageTemplates.DriftedSendCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_message_templates_drifted_send_count(p_message_template_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM message_deliveries WHERE calc_message_deliveries_drifted_send_template_key(message_delivery_id) = (SELECT NULLIF(message_template_id, '') FROM message_templates WHERE message_template_id = p_message_template_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_message_templates_unanswered_delivery_count
-- Field: MessageTemplates.UnansweredDeliveryCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_message_templates_unanswered_delivery_count(p_message_template_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM message_deliveries WHERE calc_message_deliveries_unanswered_template_key(message_delivery_id) = (SELECT NULLIF(message_template_id, '') FROM message_templates WHERE message_template_id = p_message_template_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_message_templates_transmitted_delivery_count
-- Field: MessageTemplates.TransmittedDeliveryCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_message_templates_transmitted_delivery_count(p_message_template_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM message_deliveries WHERE calc_message_deliveries_transmitted_template_key(message_delivery_id) = (SELECT NULLIF(message_template_id, '') FROM message_templates WHERE message_template_id = p_message_template_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_message_templates_template_draws_no_response
-- Field: MessageTemplates.TemplateDrawsNoResponse
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_message_templates_template_draws_no_response(p_message_template_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_message_templates_transmitted_delivery_count(p_message_template_id) AS val) SELECT ((COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE(calc_message_templates_unanswered_delivery_count(p_message_template_id), 0) = COALESCE((SELECT val FROM __erb_dedup_v1), 0), FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_semantic_mappings_name
-- Field: SemanticMappings.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_semantic_mappings_name(p_semantic_mapping_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(source_path, '') FROM semantic_mappings WHERE semantic_mapping_id = p_semantic_mapping_id), ' -> ', (SELECT NULLIF(target_iri, '') FROM semantic_mappings WHERE semantic_mapping_id = p_semantic_mapping_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_semantic_mappings_reinvents_standard_term
-- Field: SemanticMappings.ReinventsStandardTerm
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_semantic_mappings_reinvents_standard_term(p_semantic_mapping_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(mapping_relation, '') FROM semantic_mappings WHERE semantic_mapping_id = p_semantic_mapping_id), '') = 'extension', FALSE) AND COALESCE((SELECT NULLIF(available_standard_iri, '') FROM semantic_mappings WHERE semantic_mapping_id = p_semantic_mapping_id) IS NOT NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_semantic_mappings_is_non_resolvable_term_iri
-- Field: SemanticMappings.IsNonResolvableTermIri
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_semantic_mappings_is_non_resolvable_term_iri(p_semantic_mapping_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(mapping_relation, '') FROM semantic_mappings WHERE semantic_mapping_id = p_semantic_mapping_id), '') = 'extension', FALSE) AND COALESCE(COALESCE(LEFT(((SELECT NULLIF(target_iri, '') FROM semantic_mappings WHERE semantic_mapping_id = p_semantic_mapping_id))::text, (4)::integer), '') <> 'http', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

