-- calc_exception_invocations_name
-- Field: ExceptionInvocations.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_exception_invocations_name(p_exception_invocation_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(step_execution, '') FROM exception_invocations WHERE exception_invocation_id = p_exception_invocation_id), ' / ', (SELECT NULLIF(exception, '') FROM exception_invocations WHERE exception_invocation_id = p_exception_invocation_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_exception_invocations_approval_role_matches
-- Field: ExceptionInvocations.ApprovalRoleMatches
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_exception_invocations_approval_role_matches(p_exception_invocation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((SELECT NULLIF(approved_by_agent, '') FROM exception_invocations WHERE exception_invocation_id = p_exception_invocation_id), '') = COALESCE(calc_exception_invocations_required_approval_role_holder(p_exception_invocation_id), ''))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_exception_invocations_is_approved
-- Field: ExceptionInvocations.IsApproved
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_exception_invocations_is_approved(p_exception_invocation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(approved_by_agent, '') FROM exception_invocations WHERE exception_invocation_id = p_exception_invocation_id) IS NOT NULL)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_exception_invocations_is_improperly_approved
-- Field: ExceptionInvocations.IsImproperlyApproved
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_exception_invocations_is_improperly_approved(p_exception_invocation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(NOT (COALESCE(calc_exception_invocations_is_approved(p_exception_invocation_id), FALSE)), FALSE) OR COALESCE(NOT (COALESCE(calc_exception_invocations_approval_role_matches(p_exception_invocation_id), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_exception_invocations_invoker_also_prepared_key
-- Field: ExceptionInvocations.InvokerAlsoPreparedKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_exception_invocations_invoker_also_prepared_key(p_exception_invocation_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT(calc_exception_invocations_parent_procedure_execution(p_exception_invocation_id), '|', (SELECT NULLIF(approved_by_agent, '') FROM exception_invocations WHERE exception_invocation_id = p_exception_invocation_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_exception_invocations_approver_prepared_count
-- Field: ExceptionInvocations.ApproverPreparedCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_exception_invocations_approver_prepared_count(p_exception_invocation_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM step_executions WHERE calc_step_executions_preparer_agent_key(step_execution_id) = calc_exception_invocations_invoker_also_prepared_key(p_exception_invocation_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_exception_invocations_delegated_to_preparer
-- Field: ExceptionInvocations.DelegatedToPreparer
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_exception_invocations_delegated_to_preparer(p_exception_invocation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_exception_invocations_approver_prepared_count(p_exception_invocation_id))::NUMERIC, 0) > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_exception_invocations_is_ungoverned_invocation
-- Field: ExceptionInvocations.IsUngovernedInvocation
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_exception_invocations_is_ungoverned_invocation(p_exception_invocation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_exception_invocations_is_improperly_approved(p_exception_invocation_id), FALSE) OR COALESCE(calc_exception_invocations_delegated_to_preparer(p_exception_invocation_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

