-- calc_verification_outcomes_is_unbacked_observation
-- Field: VerificationOutcomes.IsUnbackedObservation
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_verification_outcomes_is_unbacked_observation(p_verification_outcome_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_verification_outcomes_signal_matches_expected(p_verification_outcome_id), FALSE) AND COALESCE(NOT (COALESCE(calc_verification_outcomes_has_evidence(p_verification_outcome_id), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_verification_outcomes_is_self_witnessed
-- Field: VerificationOutcomes.IsSelfWitnessed
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_verification_outcomes_is_self_witnessed(p_verification_outcome_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((SELECT NULLIF(observed_by_agent, '') FROM verification_outcomes WHERE verification_outcome_id = p_verification_outcome_id), '') = COALESCE(calc_verification_outcomes_step_executor_agent(p_verification_outcome_id), ''))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_verification_outcomes_self_witnessed_step_key
-- Field: VerificationOutcomes.SelfWitnessedStepKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_verification_outcomes_self_witnessed_step_key(p_verification_outcome_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_verification_outcomes_is_self_witnessed(p_verification_outcome_id) THEN ((SELECT NULLIF(step_execution, '') FROM verification_outcomes WHERE verification_outcome_id = p_verification_outcome_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_verification_outcomes_unbacked_step_key
-- Field: VerificationOutcomes.UnbackedStepKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_verification_outcomes_unbacked_step_key(p_verification_outcome_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_verification_outcomes_is_unbacked_observation(p_verification_outcome_id) THEN ((SELECT NULLIF(step_execution, '') FROM verification_outcomes WHERE verification_outcome_id = p_verification_outcome_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_verification_outcomes_is_self_witnessed_and_unbacked
-- Field: VerificationOutcomes.IsSelfWitnessedAndUnbacked
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_verification_outcomes_is_self_witnessed_and_unbacked(p_verification_outcome_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_verification_outcomes_is_self_witnessed(p_verification_outcome_id), FALSE) AND COALESCE(NOT (COALESCE(calc_verification_outcomes_has_evidence(p_verification_outcome_id), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_verification_outcomes_is_uncorroborated_pass
-- Field: VerificationOutcomes.IsUncorroboratedPass
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_verification_outcomes_is_uncorroborated_pass(p_verification_outcome_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_verification_outcomes_signal_matches_expected(p_verification_outcome_id), FALSE) AND COALESCE(calc_verification_outcomes_is_self_witnessed_and_unbacked(p_verification_outcome_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_verification_outcomes_uncorroborated_pass_step_key
-- Field: VerificationOutcomes.UncorroboratedPassStepKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_verification_outcomes_uncorroborated_pass_step_key(p_verification_outcome_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_verification_outcomes_is_uncorroborated_pass(p_verification_outcome_id) THEN ((SELECT NULLIF(step_execution, '') FROM verification_outcomes WHERE verification_outcome_id = p_verification_outcome_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_verification_outcomes_observer_is_independent_of_executor
-- Field: VerificationOutcomes.ObserverIsIndependentOfExecutor
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_verification_outcomes_observer_is_independent_of_executor(p_verification_outcome_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (NOT (COALESCE(calc_verification_outcomes_is_self_witnessed(p_verification_outcome_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_verification_outcomes_is_independent_human_observation
-- Field: VerificationOutcomes.IsIndependentHumanObservation
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_verification_outcomes_is_independent_human_observation(p_verification_outcome_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(NOT (COALESCE(calc_verification_outcomes_observer_is_non_human(p_verification_outcome_id), FALSE)), FALSE) AND COALESCE(NOT (COALESCE(calc_verification_outcomes_is_self_witnessed(p_verification_outcome_id), FALSE)), FALSE) AND COALESCE(calc_verification_outcomes_has_evidence(p_verification_outcome_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_verification_outcomes_independent_observation_execution_ke
-- Field: VerificationOutcomes.IndependentObservationExecutionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_verification_outcomes_independent_observation_execution_ke(p_verification_outcome_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_verification_outcomes_is_independent_human_observation(p_verification_outcome_id) THEN (calc_verification_outcomes_parent_procedure_execution_of_outcom(p_verification_outcome_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

