  SELECT ((SELECT COUNT(*) FROM semantic_mappings WHERE source_path = (SELECT NULLIF(rulebook_table_id, '') FROM rulebook_tables WHERE rulebook_table_id = p_rulebook_table_id) AND mapping_relation = 'exact'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_rulebook_tables_aligned_mapping_count
-- Field: RulebookTables.AlignedMappingCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_rulebook_tables_aligned_mapping_count(p_rulebook_table_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM semantic_mappings WHERE source_path = (SELECT NULLIF(rulebook_table_id, '') FROM rulebook_tables WHERE rulebook_table_id = p_rulebook_table_id) AND mapping_relation = 'aligned'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_rulebook_tables_is_unaligned_to_standard
-- Field: RulebookTables.IsUnalignedToStandard
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_rulebook_tables_is_unaligned_to_standard(p_rulebook_table_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_rulebook_tables_exact_mapping_count(p_rulebook_table_id)) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_rulebook_tables_aligned_mapping_count(p_rulebook_table_id)) AS v) __safe_numeric), 0)))::NUMERIC, 0) = 0)::boolean;
$$ LANGUAGE sql STABLE;

