-- calc_process_mining_runs_name
-- Field: ProcessMiningRuns.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_process_mining_runs_name(p_process_mining_run_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(event_log_source, '') FROM process_mining_runs WHERE process_mining_run_id = p_process_mining_run_id), ' / ', erb_datetime_text(((SELECT mined_at::timestamptz FROM process_mining_runs WHERE process_mining_run_id = p_process_mining_run_id))::timestamptz)))::text;
$$ LANGUAGE sql STABLE;

-- calc_process_mining_runs_conformance_rate
-- Field: ProcessMiningRuns.ConformanceRate
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_process_mining_runs_conformance_rate(p_process_mining_run_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN COALESCE(((SELECT discovered_variant_count FROM process_mining_runs WHERE process_mining_run_id = p_process_mining_run_id))::NUMERIC, 0) = 0 THEN (0)::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT conforming_variant_count FROM process_mining_runs WHERE process_mining_run_id = p_process_mining_run_id)) AS v) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT discovered_variant_count FROM process_mining_runs WHERE process_mining_run_id = p_process_mining_run_id)) AS v) __safe_numeric), 0), 0)))::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_process_mining_runs_is_conformant
-- Field: ProcessMiningRuns.IsConformant
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_process_mining_runs_is_conformant(p_process_mining_run_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_process_mining_runs_conformance_rate(p_process_mining_run_id))::NUMERIC, 0) >= 0.8)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_process_mining_runs_has_major_drift_from_documentation
-- Field: ProcessMiningRuns.HasMajorDriftFromDocumentation
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_process_mining_runs_has_major_drift_from_documentation(p_process_mining_run_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_process_mining_runs_conformance_rate(p_process_mining_run_id))::NUMERIC, 0) < 0.5)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_process_mining_runs_days_since_mined
-- Field: ProcessMiningRuns.DaysSinceMined
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_process_mining_runs_days_since_mined(p_process_mining_run_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((((calc_process_mining_runs_as_of_instant(p_process_mining_run_id))::timestamptz AT TIME ZONE 'UTC')::date - (((SELECT mined_at::timestamptz FROM process_mining_runs WHERE process_mining_run_id = p_process_mining_run_id))::timestamptz AT TIME ZONE 'UTC')::date))::integer;
$$ LANGUAGE sql STABLE;

-- calc_process_mining_runs_is_stale_mining_evidence
-- Field: ProcessMiningRuns.IsStaleMiningEvidence
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_process_mining_runs_is_stale_mining_evidence(p_process_mining_run_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_process_mining_runs_days_since_mined(p_process_mining_run_id))::NUMERIC, 0) > 180)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_process_mining_runs_is_drift_on_live_version
-- Field: ProcessMiningRuns.IsDriftOnLiveVersion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_process_mining_runs_is_drift_on_live_version(p_process_mining_run_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_process_mining_runs_has_major_drift_from_documentation(p_process_mining_run_id), FALSE) AND COALESCE(calc_process_mining_runs_procedure_version_is_live(p_process_mining_run_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_process_mining_runs_drifted_mining_run_key
-- Field: ProcessMiningRuns.DriftedMiningRunKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_process_mining_runs_drifted_mining_run_key(p_process_mining_run_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_process_mining_runs_is_drift_on_live_version(p_process_mining_run_id) THEN ((SELECT NULLIF(procedure_version, '') FROM process_mining_runs WHERE process_mining_run_id = p_process_mining_run_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_process_mining_runs_people_capture_complement_count
-- Field: ProcessMiningRuns.PeopleCaptureComplementCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_process_mining_runs_people_capture_complement_count(p_process_mining_run_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM collected_source_materials WHERE complements_mining_run = (SELECT NULLIF(process_mining_run_id, '') FROM process_mining_runs WHERE process_mining_run_id = p_process_mining_run_id) AND holds_reasoning_or_tacit_knowledge = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_process_mining_runs_is_deviation_unexplained_by_people
-- Field: ProcessMiningRuns.IsDeviationUnexplainedByPeople
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_process_mining_runs_is_deviation_unexplained_by_people(p_process_mining_run_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE(((SELECT discovered_variant_count FROM process_mining_runs WHERE process_mining_run_id = p_process_mining_run_id) > (SELECT conforming_variant_count FROM process_mining_runs WHERE process_mining_run_id = p_process_mining_run_id)), FALSE), FALSE) AND COALESCE(COALESCE((calc_process_mining_runs_people_capture_complement_count(p_process_mining_run_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_process_mining_runs_undocumented_path_count
-- Field: ProcessMiningRuns.UndocumentedPathCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_process_mining_runs_undocumented_path_count(p_process_mining_run_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM mined_flow_edges WHERE process_mining_run = (SELECT NULLIF(process_mining_run_id, '') FROM process_mining_runs WHERE process_mining_run_id = p_process_mining_run_id) AND calc_mined_flow_edges_is_undocumented_path(mined_flow_edge_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_process_mining_runs_has_undocumented_enacted_path
-- Field: ProcessMiningRuns.HasUndocumentedEnactedPath
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_process_mining_runs_has_undocumented_enacted_path(p_process_mining_run_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_process_mining_runs_undocumented_path_count(p_process_mining_run_id))::NUMERIC, 0) > 0)::boolean;
$$ LANGUAGE sql STABLE;

