-- calc_vocabularies_organized_material_count
-- Field: Vocabularies.OrganizedMaterialCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_vocabularies_organized_material_count(p_vocabulary_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM collected_source_materials WHERE organized_into_scheme = (SELECT NULLIF(vocabulary_id, '') FROM vocabularies WHERE vocabulary_id = p_vocabulary_id)))::integer;
