RETURNS TEXT AS $$
  SELECT (SELECT broader_term::text FROM vocabulary_terms WHERE vocabulary_term_id = (SELECT broader_term FROM vocabulary_terms WHERE vocabulary_term_id = p_vocabulary_term_id));
