-- calc_knowledge_broker_links_name
-- Field: KnowledgeBrokerLinks.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_broker_links_name(p_knowledge_broker_link_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(seeker, '') FROM knowledge_broker_links WHERE knowledge_broker_link_id = p_knowledge_broker_link_id), ' -> ', (SELECT NULLIF(broker, '') FROM knowledge_broker_links WHERE knowledge_broker_link_id = p_knowledge_broker_link_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_broker_links_days_since_consulted
-- Field: KnowledgeBrokerLinks.DaysSinceConsulted
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_knowledge_broker_links_days_since_consulted(p_knowledge_broker_link_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((((calc_knowledge_broker_links_as_of_instant(p_knowledge_broker_link_id))::timestamptz AT TIME ZONE 'UTC')::date - (((SELECT last_consulted_at::timestamptz FROM knowledge_broker_links WHERE knowledge_broker_link_id = p_knowledge_broker_link_id))::timestamptz AT TIME ZONE 'UTC')::date))::integer;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_broker_links_is_active_reliance
-- Field: KnowledgeBrokerLinks.IsActiveReliance
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_broker_links_is_active_reliance(p_knowledge_broker_link_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(NOT (COALESCE(COALESCE((SELECT NULLIF(frequency, '') FROM knowledge_broker_links WHERE knowledge_broker_link_id = p_knowledge_broker_link_id), '') = 'Rarely', FALSE)), FALSE) AND COALESCE(COALESCE((calc_knowledge_broker_links_days_since_consulted(p_knowledge_broker_link_id))::NUMERIC, 0) <= 180, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_knowledge_broker_links_is_at_risk_reliance
-- Field: KnowledgeBrokerLinks.IsAtRiskReliance
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_broker_links_is_at_risk_reliance(p_knowledge_broker_link_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_knowledge_broker_links_is_active_reliance(p_knowledge_broker_link_id), FALSE) AND COALESCE(NOT (COALESCE(calc_knowledge_broker_links_broker_is_still_engaged(p_knowledge_broker_link_id), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_broker_links_active_reliance_broker_key
-- Field: KnowledgeBrokerLinks.ActiveRelianceBrokerKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_broker_links_active_reliance_broker_key(p_knowledge_broker_link_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_knowledge_broker_links_is_active_reliance(p_knowledge_broker_link_id) THEN ((SELECT NULLIF(broker, '') FROM knowledge_broker_links WHERE knowledge_broker_link_id = p_knowledge_broker_link_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_broker_links_at_risk_broker_key
-- Field: KnowledgeBrokerLinks.AtRiskBrokerKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_broker_links_at_risk_broker_key(p_knowledge_broker_link_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_knowledge_broker_links_is_at_risk_reliance(p_knowledge_broker_link_id) THEN ((SELECT NULLIF(broker, '') FROM knowledge_broker_links WHERE knowledge_broker_link_id = p_knowledge_broker_link_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_broker_links_locates_other_holder
-- Field: KnowledgeBrokerLinks.LocatesOtherHolder
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_broker_links_locates_other_holder(p_knowledge_broker_link_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_knowledge_broker_links_pointed_holder(p_knowledge_broker_link_id) AS val) SELECT ((COALESCE((SELECT NULLIF(points_to_know_how, '') FROM knowledge_broker_links WHERE knowledge_broker_link_id = p_knowledge_broker_link_id) IS NOT NULL, FALSE) AND COALESCE((SELECT val FROM __erb_dedup_v1) IS NOT NULL, FALSE) AND COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') <> COALESCE((SELECT NULLIF(broker, '') FROM knowledge_broker_links WHERE knowledge_broker_link_id = p_knowledge_broker_link_id), ''), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_broker_links_translation_between_vocabularies
-- Field: KnowledgeBrokerLinks.TranslationBetweenVocabularies
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_broker_links_translation_between_vocabularies(p_knowledge_broker_link_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN (COALESCE((SELECT NULLIF(seeker_vocabulary, '') FROM knowledge_broker_links WHERE knowledge_broker_link_id = p_knowledge_broker_link_id) IS NOT NULL, FALSE) AND COALESCE((SELECT NULLIF(holder_vocabulary, '') FROM knowledge_broker_links WHERE knowledge_broker_link_id = p_knowledge_broker_link_id) IS NOT NULL, FALSE) AND COALESCE(COALESCE((SELECT NULLIF(seeker_vocabulary, '') FROM knowledge_broker_links WHERE knowledge_broker_link_id = p_knowledge_broker_link_id), '') <> COALESCE((SELECT NULLIF(holder_vocabulary, '') FROM knowledge_broker_links WHERE knowledge_broker_link_id = p_knowledge_broker_link_id), ''), FALSE)) THEN (CONCAT((SELECT NULLIF(seeker_wording, '') FROM knowledge_broker_links WHERE knowledge_broker_link_id = p_knowledge_broker_link_id), ' (', (SELECT NULLIF(seeker_vocabulary, '') FROM knowledge_broker_links WHERE knowledge_broker_link_id = p_knowledge_broker_link_id), ') = ', (SELECT NULLIF(holder_wording, '') FROM knowledge_broker_links WHERE knowledge_broker_link_id = p_knowledge_broker_link_id), ' (', (SELECT NULLIF(holder_vocabulary, '') FROM knowledge_broker_links WHERE knowledge_broker_link_id = p_knowledge_broker_link_id), ')'))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

