-- calc_article_claims_name
-- Field: ArticleClaims.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_article_claims_name(p_article_claim_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(article_claim_id, '') FROM article_claims WHERE article_claim_id = p_article_claim_id), ': ', LEFT(((SELECT NULLIF(claim_text, '') FROM article_claims WHERE article_claim_id = p_article_claim_id))::text, (60)::integer)))::text;
$$ LANGUAGE sql STABLE;

-- calc_article_claims_required_evidence
-- Field: ArticleClaims.RequiredEvidence
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_article_claims_required_evidence(p_article_claim_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((SELECT NULLIF(claim_kind, '') FROM article_claims WHERE article_claim_id = p_article_claim_id), '') = 'Concept' THEN ('a table with rows or a field with data')::text ELSE (CASE WHEN COALESCE((SELECT NULLIF(claim_kind, '') FROM article_claims WHERE article_claim_id = p_article_claim_id), '') = 'CompetencyQuestion' THEN ('an answered role question with a computed answer')::text ELSE (CASE WHEN COALESCE((SELECT NULLIF(claim_kind, '') FROM article_claims WHERE article_claim_id = p_article_claim_id), '') = 'Standard' THEN ('a mapped ontology profile or an applied knowledge method')::text ELSE (CASE WHEN COALESCE((SELECT NULLIF(claim_kind, '') FROM article_claims WHERE article_claim_id = p_article_claim_id), '') = 'Scenario' THEN ('a procedure with recorded executions')::text ELSE ('a discriminating witness invented for a role question')::text END)::text END)::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_article_claims_evidence_count
-- Field: ArticleClaims.EvidenceCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_article_claims_evidence_count(p_article_claim_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM claim_evidence WHERE article_claim = (SELECT NULLIF(article_claim_id, '') FROM article_claims WHERE article_claim_id = p_article_claim_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_article_claims_valid_evidence_count
-- Field: ArticleClaims.ValidEvidenceCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_article_claims_valid_evidence_count(p_article_claim_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM claim_evidence WHERE article_claim = (SELECT NULLIF(article_claim_id, '') FROM article_claims WHERE article_claim_id = p_article_claim_id) AND calc_claim_evidence_is_valid(claim_evidence_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_article_claims_agreed_evidence_count
-- Field: ArticleClaims.AgreedEvidenceCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_article_claims_agreed_evidence_count(p_article_claim_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM claim_evidence WHERE article_claim = (SELECT NULLIF(article_claim_id, '') FROM article_claims WHERE article_claim_id = p_article_claim_id) AND calc_claim_evidence_is_agreed_evidence(claim_evidence_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_article_claims_is_covered
-- Field: ArticleClaims.IsCovered
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_article_claims_is_covered(p_article_claim_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_article_claims_valid_evidence_count(p_article_claim_id))::NUMERIC, 0) > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_article_claims_is_agreed
-- Field: ArticleClaims.IsAgreed
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_article_claims_is_agreed(p_article_claim_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_article_claims_agreed_evidence_count(p_article_claim_id))::NUMERIC, 0) > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_article_claims_has_rejected_evidence
-- Field: ArticleClaims.HasRejectedEvidence
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_article_claims_has_rejected_evidence(p_article_claim_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_article_claims_evidence_count(p_article_claim_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_article_claims_valid_evidence_count(p_article_claim_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

