-- calc_claim_evidence_name
-- Field: ClaimEvidence.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_claim_evidence_name(p_claim_evidence_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(article_claim, '') FROM claim_evidence WHERE claim_evidence_id = p_claim_evidence_id), ' <- ', (SELECT NULLIF(evidence_kind, '') FROM claim_evidence WHERE claim_evidence_id = p_claim_evidence_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_claim_evidence_has_justification
-- Field: ClaimEvidence.HasJustification
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_claim_evidence_has_justification(p_claim_evidence_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(justification, '') FROM claim_evidence WHERE claim_evidence_id = p_claim_evidence_id) IS NOT NULL)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_claim_evidence_is_witness_proof
-- Field: ClaimEvidence.IsWitnessProof
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_claim_evidence_is_witness_proof(p_claim_evidence_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(evidence_kind, '') FROM claim_evidence WHERE claim_evidence_id = p_claim_evidence_id), '') = 'Field', FALSE) AND COALESCE(calc_claim_evidence_field_catalog_name(p_claim_evidence_id) IS NOT NULL, FALSE) AND COALESCE(calc_claim_evidence_field_is_witness(p_claim_evidence_id), FALSE) AND COALESCE(calc_claim_evidence_field_is_discriminating(p_claim_evidence_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_claim_evidence_is_structural_proof
-- Field: ClaimEvidence.IsStructuralProof
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_claim_evidence_is_structural_proof(p_claim_evidence_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((COALESCE(COALESCE((SELECT NULLIF(evidence_kind, '') FROM claim_evidence WHERE claim_evidence_id = p_claim_evidence_id), '') = 'Table', FALSE) AND COALESCE(calc_claim_evidence_table_has_rows(p_claim_evidence_id), FALSE)), FALSE) OR COALESCE((COALESCE(COALESCE((SELECT NULLIF(evidence_kind, '') FROM claim_evidence WHERE claim_evidence_id = p_claim_evidence_id), '') = 'Field', FALSE) AND COALESCE(calc_claim_evidence_field_catalog_name(p_claim_evidence_id) IS NOT NULL, FALSE) AND COALESCE(calc_claim_evidence_field_has_data(p_claim_evidence_id), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_claim_evidence_is_question_proof
-- Field: ClaimEvidence.IsQuestionProof
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_claim_evidence_is_question_proof(p_claim_evidence_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(evidence_kind, '') FROM claim_evidence WHERE claim_evidence_id = p_claim_evidence_id), '') = 'RoleQuestion', FALSE) AND COALESCE(calc_claim_evidence_question_is_answered(p_claim_evidence_id), FALSE) AND COALESCE(calc_claim_evidence_question_witnessed_answer(p_claim_evidence_id) IS NOT NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_claim_evidence_is_standard_proof
-- Field: ClaimEvidence.IsStandardProof
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_claim_evidence_is_standard_proof(p_claim_evidence_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((COALESCE(COALESCE((SELECT NULLIF(evidence_kind, '') FROM claim_evidence WHERE claim_evidence_id = p_claim_evidence_id), '') = 'OntologyProfile', FALSE) AND COALESCE(COALESCE((calc_claim_evidence_profile_mapping_count(p_claim_evidence_id))::NUMERIC, 0) > 0, FALSE)), FALSE) OR COALESCE((COALESCE(COALESCE((SELECT NULLIF(evidence_kind, '') FROM claim_evidence WHERE claim_evidence_id = p_claim_evidence_id), '') = 'KnowledgeMethod', FALSE) AND COALESCE(calc_claim_evidence_method_is_applied(p_claim_evidence_id), FALSE)), FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_claim_evidence_is_scenario_proof
-- Field: ClaimEvidence.IsScenarioProof
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_claim_evidence_is_scenario_proof(p_claim_evidence_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(evidence_kind, '') FROM claim_evidence WHERE claim_evidence_id = p_claim_evidence_id), '') = 'Procedure', FALSE) AND COALESCE(COALESCE((calc_claim_evidence_procedure_execution_count(p_claim_evidence_id))::NUMERIC, 0) > 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_claim_evidence_is_valid
-- Field: ClaimEvidence.IsValid
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_claim_evidence_is_valid(p_claim_evidence_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_claim_evidence_claim_kind(p_claim_evidence_id) AS val) SELECT ((COALESCE(calc_claim_evidence_has_justification(p_claim_evidence_id), FALSE) AND COALESCE((COALESCE((COALESCE((COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'Prescription', FALSE) OR COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'Illustration', FALSE)), FALSE) AND COALESCE(calc_claim_evidence_is_witness_proof(p_claim_evidence_id), FALSE)), FALSE) OR COALESCE((COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'Concept', FALSE) AND COALESCE(calc_claim_evidence_is_structural_proof(p_claim_evidence_id), FALSE)), FALSE) OR COALESCE((COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'CompetencyQuestion', FALSE) AND COALESCE(calc_claim_evidence_is_question_proof(p_claim_evidence_id), FALSE)), FALSE) OR COALESCE((COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'Standard', FALSE) AND COALESCE(calc_claim_evidence_is_standard_proof(p_claim_evidence_id), FALSE)), FALSE) OR COALESCE((COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'Scenario', FALSE) AND COALESCE(calc_claim_evidence_is_scenario_proof(p_claim_evidence_id), FALSE)), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_claim_evidence_is_contested
-- Field: ClaimEvidence.IsContested
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_claim_evidence_is_contested(p_claim_evidence_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(evidence_kind, '') FROM claim_evidence WHERE claim_evidence_id = p_claim_evidence_id), '') = 'Field', FALSE) AND COALESCE(calc_claim_evidence_field_is_contested(p_claim_evidence_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_claim_evidence_is_agreed_evidence
-- Field: ClaimEvidence.IsAgreedEvidence
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_claim_evidence_is_agreed_evidence(p_claim_evidence_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_claim_evidence_is_valid(p_claim_evidence_id), FALSE) AND COALESCE(COALESCE(calc_claim_evidence_is_contested(p_claim_evidence_id), FALSE) = FALSE, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

