-- calc_facilities_is_deviation_only_facility
-- Field: Facilities.IsDeviationOnlyFacility
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_facilities_is_deviation_only_facility(p_facility_id TEXT)
