  SELECT ((COALESCE(COALESCE((calc_facilities_deviating_run_count(p_facility_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_facilities_clean_run_count(p_facility_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

