-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_machine_energy_sources_unisolated_machine_key(p_machine_energy_source_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_machine_energy_sources_is_unisolated_energy_source(p_machine_energy_source_id) THEN ((SELECT NULLIF(machine, '') FROM machine_energy_sources WHERE machine_energy_source_id = p_machine_energy_source_id))::text ELSE ('')::text END)::text;
