RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(step_execution, '') FROM execution_entities WHERE execution_entity_id = p_execution_entity_id), ' ', (SELECT NULLIF(usage, '') FROM execution_entities WHERE execution_entity_id = p_execution_entity_id), ' ', (SELECT NULLIF(entity_label, '') FROM execution_entities WHERE execution_entity_id = p_execution_entity_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_execution_entities_is_usage_direction_mismatch
-- Field: ExecutionEntities.IsUsageDirectionMismatch
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_execution_entities_is_usage_direction_mismatch(p_execution_entity_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_execution_entities_variable_direction(p_execution_entity_id) AS val) SELECT ((COALESCE((COALESCE(COALESCE((SELECT NULLIF(usage, '') FROM execution_entities WHERE execution_entity_id = p_execution_entity_id), '') = 'Used', FALSE) AND COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') <> 'Input', FALSE)), FALSE) OR COALESCE((COALESCE(COALESCE((SELECT NULLIF(usage, '') FROM execution_entities WHERE execution_entity_id = p_execution_entity_id), '') = 'Generated', FALSE) AND COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') <> 'Output', FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_execution_entities_is_foreign_variable
-- Field: ExecutionEntities.IsForeignVariable
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_execution_entities_is_foreign_variable(p_execution_entity_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE(calc_execution_entities_variable_step(p_execution_entity_id), '') <> COALESCE(calc_execution_entities_executed_step(p_execution_entity_id), ''))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_execution_entities_used_execution_key
-- Field: ExecutionEntities.UsedExecutionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_execution_entities_used_execution_key(p_execution_entity_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((SELECT NULLIF(usage, '') FROM execution_entities WHERE execution_entity_id = p_execution_entity_id), '') = 'Used' THEN ((SELECT NULLIF(step_execution, '') FROM execution_entities WHERE execution_entity_id = p_execution_entity_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_execution_entities_generated_execution_key
-- Field: ExecutionEntities.GeneratedExecutionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_execution_entities_generated_execution_key(p_execution_entity_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((SELECT NULLIF(usage, '') FROM execution_entities WHERE execution_entity_id = p_execution_entity_id), '') = 'Generated' THEN ((SELECT NULLIF(step_execution, '') FROM execution_entities WHERE execution_entity_id = p_execution_entity_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_execution_entities_violates_declared_datatype_or_format
-- Field: ExecutionEntities.ViolatesDeclaredDatatypeOrFormat
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_execution_entities_violates_declared_datatype_or_format(p_execution_entity_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_execution_entities_variable_expected_format(p_execution_entity_id) AS val) SELECT ((COALESCE((COALESCE((SELECT NULLIF(recorded_datatype, '') FROM execution_entities WHERE execution_entity_id = p_execution_entity_id) IS NOT NULL, FALSE) AND COALESCE(COALESCE((SELECT NULLIF(recorded_datatype, '') FROM execution_entities WHERE execution_entity_id = p_execution_entity_id), '') <> COALESCE(calc_execution_entities_variable_datatype(p_execution_entity_id), ''), FALSE)), FALSE) OR COALESCE((COALESCE((SELECT NULLIF(recorded_format, '') FROM execution_entities WHERE execution_entity_id = p_execution_entity_id) IS NOT NULL, FALSE) AND COALESCE((SELECT val FROM __erb_dedup_v1) IS NOT NULL, FALSE) AND COALESCE(COALESCE((SELECT NULLIF(recorded_format, '') FROM execution_entities WHERE execution_entity_id = p_execution_entity_id), '') <> COALESCE((SELECT val FROM __erb_dedup_v1), ''), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_execution_entities_attributed_to_agent
-- Field: ExecutionEntities.AttributedToAgent
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_execution_entities_attributed_to_agent(p_execution_entity_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((SELECT NULLIF(usage, '') FROM execution_entities WHERE execution_entity_id = p_execution_entity_id), '') = 'Generated' THEN (calc_execution_entities_generating_agent(p_execution_entity_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

