-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_condition_checks_failed_precondition_execution_key(p_condition_check_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_condition_checks_is_failed_precondition(p_condition_check_id) THEN ((SELECT NULLIF(step_execution, '') FROM condition_checks WHERE condition_check_id = p_condition_check_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

