-- calc_process_knowledge_levels_tacit_strategy_count
-- Field: ProcessKnowledgeLevels.TacitStrategyCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_process_knowledge_levels_tacit_strategy_count(p_process_knowledge_level_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM level_capture_strategies WHERE level = (SELECT NULLIF(process_knowledge_level_id, '') FROM process_knowledge_levels WHERE process_knowledge_level_id = p_process_knowledge_level_id) AND knowledge_form = 'Tacit'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_process_knowledge_levels_explicit_strategy_count
-- Field: ProcessKnowledgeLevels.ExplicitStrategyCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_process_knowledge_levels_explicit_strategy_count(p_process_knowledge_level_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM level_capture_strategies WHERE level = (SELECT NULLIF(process_knowledge_level_id, '') FROM process_knowledge_levels WHERE process_knowledge_level_id = p_process_knowledge_level_id) AND knowledge_form = 'Explicit'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_process_knowledge_levels_lacks_capture_strategy_for_either
-- Field: ProcessKnowledgeLevels.LacksCaptureStrategyForEitherForm
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_process_knowledge_levels_lacks_capture_strategy_for_either(p_process_knowledge_level_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_process_knowledge_levels_tacit_strategy_count(p_process_knowledge_level_id))::NUMERIC, 0) = 0, FALSE) OR COALESCE(COALESCE((calc_process_knowledge_levels_explicit_strategy_count(p_process_knowledge_level_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

