$$ LANGUAGE sql STABLE;

-- calc_procedure_lens_views_view_granularity_rank
-- Field: ProcedureLensViews.ViewGranularityRank
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_procedure_lens_views_view_granularity_rank(p_procedure_lens_view_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE((SELECT NULLIF(granularity, '') FROM procedure_lens_views WHERE procedure_lens_view_id = p_procedure_lens_view_id), '') = 'Step' THEN (3)::text ELSE (CASE WHEN COALESCE((SELECT NULLIF(granularity, '') FROM procedure_lens_views WHERE procedure_lens_view_id = p_procedure_lens_view_id), '') = 'Stage' THEN (2)::text ELSE (CASE WHEN COALESCE((SELECT NULLIF(granularity, '') FROM procedure_lens_views WHERE procedure_lens_view_id = p_procedure_lens_view_id), '') = 'Category' THEN (1)::text ELSE (0)::text END)::text END)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_procedure_lens_views_is_granularity_misfit
-- Field: ProcedureLensViews.IsGranularityMisfit
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_procedure_lens_views_is_granularity_misfit(p_procedure_lens_view_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_procedure_lens_views_lens_granularity_rank(p_procedure_lens_view_id) AS val) SELECT ((COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE(calc_procedure_lens_views_view_granularity_rank(p_procedure_lens_view_id), 0) <> COALESCE((SELECT val FROM __erb_dedup_v1), 0), FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_procedure_lens_views_is_disconnected_silo
-- Field: ProcedureLensViews.IsDisconnectedSilo
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_procedure_lens_views_is_disconnected_silo(p_procedure_lens_view_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(projects_version, '') FROM procedure_lens_views WHERE procedure_lens_view_id = p_procedure_lens_view_id) IS NULL, FALSE) OR COALESCE(COALESCE((SELECT NULLIF(projects_version, '') FROM procedure_lens_views WHERE procedure_lens_view_id = p_procedure_lens_view_id), '') <> COALESCE(calc_procedure_lens_views_procedure_current_version(p_procedure_lens_view_id), ''), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_procedure_lens_views_step_level_procedure_key
-- Field: ProcedureLensViews.StepLevelProcedureKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_procedure_lens_views_step_level_procedure_key(p_procedure_lens_view_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((calc_procedure_lens_views_lens_granularity_rank(p_procedure_lens_view_id))::NUMERIC, 0) = 3 THEN ((SELECT NULLIF(procedure, '') FROM procedure_lens_views WHERE procedure_lens_view_id = p_procedure_lens_view_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_procedure_lens_views_category_level_procedure_key
-- Field: ProcedureLensViews.CategoryLevelProcedureKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_procedure_lens_views_category_level_procedure_key(p_procedure_lens_view_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((calc_procedure_lens_views_lens_granularity_rank(p_procedure_lens_view_id))::NUMERIC, 0) = 1 THEN ((SELECT NULLIF(procedure, '') FROM procedure_lens_views WHERE procedure_lens_view_id = p_procedure_lens_view_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_applicability_scopes_name
-- Field: ApplicabilityScopes.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_applicability_scopes_name(p_applicability_scope_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(label, '') FROM applicability_scopes WHERE applicability_scope_id = p_applicability_scope_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_applicability_scopes_dimension_count
-- Field: ApplicabilityScopes.DimensionCount
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_applicability_scopes_dimension_count(p_applicability_scope_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN (SELECT NULLIF(business_unit, '') FROM applicability_scopes WHERE applicability_scope_id = p_applicability_scope_id) IS NOT NULL THEN (1)::text ELSE (0)::text END) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN (SELECT NULLIF(geography, '') FROM applicability_scopes WHERE applicability_scope_id = p_applicability_scope_id) IS NOT NULL THEN (1)::text ELSE (0)::text END) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN (SELECT NULLIF(customer_segment, '') FROM applicability_scopes WHERE applicability_scope_id = p_applicability_scope_id) IS NOT NULL THEN (1)::text ELSE (0)::text END) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN (SELECT NULLIF(regulatory_regime, '') FROM applicability_scopes WHERE applicability_scope_id = p_applicability_scope_id) IS NOT NULL THEN (1)::text ELSE (0)::text END) AS v) __safe_numeric), 0))) AS v) __safe_numeric), 0))) AS v) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_applicability_scopes_states_conditions
-- Field: ApplicabilityScopes.StatesConditions
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_applicability_scopes_states_conditions(p_applicability_scope_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(applies_when, '') FROM applicability_scopes WHERE applicability_scope_id = p_applicability_scope_id) IS NOT NULL, FALSE) OR COALESCE((SELECT NULLIF(exclusion_condition, '') FROM applicability_scopes WHERE applicability_scope_id = p_applicability_scope_id) IS NOT NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

