-- calc_collected_source_materials_dependent_trace_count
-- Field: CollectedSourceMaterials.DependentTraceCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_collected_source_materials_dependent_trace_count(p_collected_source_material_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM knowledge_traces WHERE source_material = (SELECT NULLIF(collected_source_material_id, '') FROM collected_source_materials WHERE collected_source_material_id = p_collected_source_material_id)))::integer;
