CREATE OR REPLACE FUNCTION calc_collected_source_materials_has_knowledge_affected_by_sourc(p_collected_source_material_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_collected_source_materials_changed_dependent_count(p_collected_source_material_id))::NUMERIC, 0) > 0)::boolean;
