-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_term_label_variants_name(p_term_label_variant_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(vocabulary_term, '') FROM term_label_variants WHERE term_label_variant_id = p_term_label_variant_id), ' ', (SELECT NULLIF(label_kind, '') FROM term_label_variants WHERE term_label_variant_id = p_term_label_variant_id), ': ', (SELECT NULLIF(wording, '') FROM term_label_variants WHERE term_label_variant_id = p_term_label_variant_id)))::text;
