CREATE OR REPLACE FUNCTION calc_term_label_variants_wording_key(p_term_label_variant_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT(calc_term_label_variants_term_scheme(p_term_label_variant_id), '|', (SELECT NULLIF(wording, '') FROM term_label_variants WHERE term_label_variant_id = p_term_label_variant_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_term_label_variants_pref_wording_key
