-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_term_label_variants_pref_wording_key(p_term_label_variant_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((SELECT NULLIF(label_kind, '') FROM term_label_variants WHERE term_label_variant_id = p_term_label_variant_id), '') = 'pref' THEN (calc_term_label_variants_wording_key(p_term_label_variant_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

