-- Field: SourceTermMentions.IsNonCanonicalGeneratedValue
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_source_term_mentions_is_non_canonical_generated_value(p_source_term_mention_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(mention_origin, '') FROM source_term_mentions WHERE source_term_mention_id = p_source_term_mention_id), '') = 'AIGenerated', FALSE) AND COALESCE(COALESCE((calc_source_term_mentions_matching_pref_label_count(p_source_term_mention_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_source_term_mentions_unresolved_intended_term_key
