  SELECT (CASE WHEN COALESCE((calc_source_term_mentions_matching_label_count(p_source_term_mention_id))::NUMERIC, 0) = 0 THEN (calc_source_term_mentions_intended_term_role(p_source_term_mention_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

