CREATE OR REPLACE FUNCTION calc_term_relations_asserts_indirect_link_as_direct(p_term_relation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(relation_kind, '') FROM term_relations WHERE term_relation_id = p_term_relation_id), '') = 'broader', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(to_term, '') FROM term_relations WHERE term_relation_id = p_term_relation_id), '') = COALESCE(calc_term_relations_from_term_grandparent(p_term_relation_id), ''), FALSE)))::boolean;
