-- calc_consumer_system_syncs_name
-- Field: ConsumerSystemSyncs.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_consumer_system_syncs_name(p_consumer_system_sync_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(consumer_system, '') FROM consumer_system_syncs WHERE consumer_system_sync_id = p_consumer_system_sync_id), ' holds ', (SELECT NULLIF(loaded_version, '') FROM consumer_system_syncs WHERE consumer_system_sync_id = p_consumer_system_sync_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_consumer_system_syncs_is_behind_canonical_version
-- Field: ConsumerSystemSyncs.IsBehindCanonicalVersion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_consumer_system_syncs_is_behind_canonical_version(p_consumer_system_sync_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_consumer_system_syncs_canonical_version(p_consumer_system_sync_id) AS val) SELECT ((COALESCE((SELECT val FROM __erb_dedup_v1) IS NOT NULL, FALSE) AND COALESCE(COALESCE((SELECT NULLIF(loaded_version, '') FROM consumer_system_syncs WHERE consumer_system_sync_id = p_consumer_system_sync_id), '') <> COALESCE((SELECT val FROM __erb_dedup_v1), ''), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_consumer_system_syncs_predates_version_change
-- Field: ConsumerSystemSyncs.PredatesVersionChange
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_consumer_system_syncs_predates_version_change(p_consumer_system_sync_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(loaded_version, '') FROM consumer_system_syncs WHERE consumer_system_sync_id = p_consumer_system_sync_id), '') = COALESCE(calc_consumer_system_syncs_canonical_version(p_consumer_system_sync_id), ''), FALSE) AND COALESCE(COALESCE(((SELECT synced_at::timestamptz FROM consumer_system_syncs WHERE consumer_system_sync_id = p_consumer_system_sync_id) < calc_consumer_system_syncs_canonical_version_modified_at(p_consumer_system_sync_id)), FALSE), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_consumer_system_syncs_is_ai_fed_from_forked_copy
-- Field: ConsumerSystemSyncs.IsAiFedFromForkedCopy
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_consumer_system_syncs_is_ai_fed_from_forked_copy(p_consumer_system_sync_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE(calc_consumer_system_syncs_system_audience(p_consumer_system_sync_id), '') <> 'Human', FALSE) AND COALESCE((SELECT NULLIF(source_resource, '') FROM consumer_system_syncs WHERE consumer_system_sync_id = p_consumer_system_sync_id) IS NOT NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_consumer_system_syncs_drops_provenance_in_transit
