CREATE OR REPLACE FUNCTION calc_consumer_system_syncs_drops_provenance_in_transit(p_consumer_system_sync_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_consumer_system_syncs_loaded_version_creator(p_consumer_system_sync_id) IS NOT NULL, FALSE) AND COALESCE(COALESCE((SELECT carries_provenance FROM consumer_system_syncs WHERE consumer_system_sync_id = p_consumer_system_sync_id), FALSE) = FALSE, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_consumer_system_syncs_reaches_humans
-- Field: ConsumerSystemSyncs.ReachesHumans
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_consumer_system_syncs_reaches_humans(p_consumer_system_sync_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_consumer_system_syncs_system_audience(p_consumer_system_sync_id) AS val) SELECT ((COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'Human', FALSE) OR COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'Both', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

