CREATE OR REPLACE FUNCTION calc_grounding_snapshots_reasoner_run_count(p_grounding_snapshot_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM reasoner_runs WHERE snapshot = (SELECT NULLIF(grounding_snapshot_id, '') FROM grounding_snapshots WHERE grounding_snapshot_id = p_grounding_snapshot_id)))::integer;
