-- calc_assistant_answers_name
-- Field: AssistantAnswers.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_assistant_answers_name(p_assistant_answer_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(answering_agent, '') FROM assistant_answers WHERE assistant_answer_id = p_assistant_answer_id), ': ', LEFT(((SELECT NULLIF(question_text, '') FROM assistant_answers WHERE assistant_answer_id = p_assistant_answer_id))::text, (50)::integer)))::text;
$$ LANGUAGE sql STABLE;

-- calc_assistant_answers_grounding_count
-- Field: AssistantAnswers.GroundingCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_assistant_answers_grounding_count(p_assistant_answer_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM answer_groundings WHERE assistant_answer = (SELECT NULLIF(assistant_answer_id, '') FROM assistant_answers WHERE assistant_answer_id = p_assistant_answer_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_assistant_answers_own_knowledge_grounding_count
-- Field: AssistantAnswers.OwnKnowledgeGroundingCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_assistant_answers_own_knowledge_grounding_count(p_assistant_answer_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM answer_groundings WHERE assistant_answer = (SELECT NULLIF(assistant_answer_id, '') FROM assistant_answers WHERE assistant_answer_id = p_assistant_answer_id) AND calc_answer_groundings_is_from_own_knowledge(answer_grounding_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_assistant_answers_cited_grounding_count
-- Field: AssistantAnswers.CitedGroundingCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_assistant_answers_cited_grounding_count(p_assistant_answer_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM answer_groundings WHERE assistant_answer = (SELECT NULLIF(assistant_answer_id, '') FROM assistant_answers WHERE assistant_answer_id = p_assistant_answer_id) AND cited_to_user = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_assistant_answers_stale_grounding_count
-- Field: AssistantAnswers.StaleGroundingCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_assistant_answers_stale_grounding_count(p_assistant_answer_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM answer_groundings WHERE assistant_answer = (SELECT NULLIF(assistant_answer_id, '') FROM assistant_answers WHERE assistant_answer_id = p_assistant_answer_id) AND calc_answer_groundings_grounds_on_stale_assertion(answer_grounding_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_assistant_answers_is_not_from_own_knowledge
-- Field: AssistantAnswers.IsNotFromOwnKnowledge
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_assistant_answers_is_not_from_own_knowledge(p_assistant_answer_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(delivery_disposition, '') FROM assistant_answers WHERE assistant_answer_id = p_assistant_answer_id), '') = 'Delivered', FALSE) AND COALESCE(COALESCE((calc_assistant_answers_own_knowledge_grounding_count(p_assistant_answer_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_assistant_answers_is_untraceable_to_source
-- Field: AssistantAnswers.IsUntraceableToSource
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_assistant_answers_is_untraceable_to_source(p_assistant_answer_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(delivery_disposition, '') FROM assistant_answers WHERE assistant_answer_id = p_assistant_answer_id), '') = 'Delivered', FALSE) AND COALESCE(COALESCE((calc_assistant_answers_grounding_count(p_assistant_answer_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_assistant_answers_cited_grounding_count(p_assistant_answer_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_assistant_answers_stayed_silent_on_safety_problem
-- Field: AssistantAnswers.StayedSilentOnSafetyProblem
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_assistant_answers_stayed_silent_on_safety_problem(p_assistant_answer_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_assistant_answers_context_unescalated_danger_cue_count(p_assistant_answer_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((SELECT raised_safety_concern FROM assistant_answers WHERE assistant_answer_id = p_assistant_answer_id), FALSE) = FALSE, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_assistant_answers_arrived_after_step_ended
-- Field: AssistantAnswers.ArrivedAfterStepEnded
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_assistant_answers_arrived_after_step_ended(p_assistant_answer_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_assistant_answers_context_step_ended_at(p_assistant_answer_id) AS val) SELECT ((COALESCE(COALESCE((SELECT NULLIF(answer_kind, '') FROM assistant_answers WHERE assistant_answer_id = p_assistant_answer_id), '') = 'Guidance', FALSE) AND COALESCE((SELECT val FROM __erb_dedup_v1) IS NOT NULL, FALSE) AND COALESCE(COALESCE(((SELECT answered_at::timestamptz FROM assistant_answers WHERE assistant_answer_id = p_assistant_answer_id) > (SELECT val FROM __erb_dedup_v1)), FALSE), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_assistant_answers_assumed_step_completed_count
-- Field: AssistantAnswers.AssumedStepCompletedCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_assistant_answers_assumed_step_completed_count(p_assistant_answer_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM step_executions WHERE procedure_execution = calc_assistant_answers_execution_of_context(p_assistant_answer_id) AND step = (SELECT NULLIF(assumed_current_step, '') FROM assistant_answers WHERE assistant_answer_id = p_assistant_answer_id) AND execution_status = 'Completed'))::integer;
$$ LANGUAGE sql STABLE;

-- calc_assistant_answers_lost_track_of_state
-- Field: AssistantAnswers.LostTrackOfState
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_assistant_answers_lost_track_of_state(p_assistant_answer_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(assumed_current_step, '') FROM assistant_answers WHERE assistant_answer_id = p_assistant_answer_id) IS NOT NULL, FALSE) AND COALESCE(calc_assistant_answers_execution_of_context(p_assistant_answer_id) IS NOT NULL, FALSE) AND COALESCE(COALESCE((calc_assistant_answers_assumed_step_completed_count(p_assistant_answer_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_assistant_answers_specified_transition_count
-- Field: AssistantAnswers.SpecifiedTransitionCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_assistant_answers_specified_transition_count(p_assistant_answer_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM step_transitions WHERE from_step = (SELECT NULLIF(assumed_current_step, '') FROM assistant_answers WHERE assistant_answer_id = p_assistant_answer_id) AND to_step = (SELECT NULLIF(asserted_next_step, '') FROM assistant_answers WHERE assistant_answer_id = p_assistant_answer_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_assistant_answers_contradicts_shared_model
-- Field: AssistantAnswers.ContradictsSharedModel
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_assistant_answers_contradicts_shared_model(p_assistant_answer_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(asserted_next_step, '') FROM assistant_answers WHERE assistant_answer_id = p_assistant_answer_id) IS NOT NULL, FALSE) AND COALESCE(COALESCE((calc_assistant_answers_specified_transition_count(p_assistant_answer_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_assistant_answers_is_explicitly_grounded_recommendation
-- Field: AssistantAnswers.IsExplicitlyGroundedRecommendation
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_assistant_answers_is_explicitly_grounded_recommendation(p_assistant_answer_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(answer_kind, '') FROM assistant_answers WHERE assistant_answer_id = p_assistant_answer_id), '') = 'Recommendation', FALSE) AND COALESCE(COALESCE((calc_assistant_answers_own_knowledge_grounding_count(p_assistant_answer_id))::NUMERIC, 0) > 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_assistant_answers_recommendation_rests_on_nothing_explicit
-- Field: AssistantAnswers.RecommendationRestsOnNothingExplicit
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_assistant_answers_recommendation_rests_on_nothing_explicit(p_assistant_answer_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(answer_kind, '') FROM assistant_answers WHERE assistant_answer_id = p_assistant_answer_id), '') = 'Recommendation', FALSE) AND COALESCE(COALESCE((calc_assistant_answers_own_knowledge_grounding_count(p_assistant_answer_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_assistant_answers_requirement_check_count
-- Field: AssistantAnswers.RequirementCheckCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_assistant_answers_requirement_check_count(p_assistant_answer_id TEXT)
