$$ LANGUAGE sql STABLE;

-- calc_prompt_templates_child_template_count
-- Field: PromptTemplates.ChildTemplateCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_prompt_templates_child_template_count(p_prompt_template_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM prompt_templates WHERE parent_template = (SELECT NULLIF(prompt_template_id, '') FROM prompt_templates WHERE prompt_template_id = p_prompt_template_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_prompt_templates_is_disconnected_prompt_knowledge
-- Field: PromptTemplates.IsDisconnectedPromptKnowledge
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_prompt_templates_is_disconnected_prompt_knowledge(p_prompt_template_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT carries_procedure_instructions FROM prompt_templates WHERE prompt_template_id = p_prompt_template_id), FALSE), FALSE) AND COALESCE((SELECT NULLIF(source_procedure_version, '') FROM prompt_templates WHERE prompt_template_id = p_prompt_template_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_prompt_templates_is_unmanaged_prompt_in_use
-- Field: PromptTemplates.IsUnmanagedPromptInUse
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_prompt_templates_is_unmanaged_prompt_in_use(p_prompt_template_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(used_by_agent, '') FROM prompt_templates WHERE prompt_template_id = p_prompt_template_id) IS NOT NULL, FALSE) AND COALESCE((COALESCE(COALESCE((SELECT NULLIF(library_status, '') FROM prompt_templates WHERE prompt_template_id = p_prompt_template_id), '') <> 'Maintained', FALSE) OR COALESCE((SELECT NULLIF(maintained_by_role, '') FROM prompt_templates WHERE prompt_template_id = p_prompt_template_id) IS NULL, FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_prompt_templates_spends_budget_on_rare_detail
-- Field: PromptTemplates.SpendsBudgetOnRareDetail
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_prompt_templates_spends_budget_on_rare_detail(p_prompt_template_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT includes_rare_detail FROM prompt_templates WHERE prompt_template_id = p_prompt_template_id), FALSE), FALSE) AND COALESCE(COALESCE(((SELECT estimated_tokens FROM prompt_templates WHERE prompt_template_id = p_prompt_template_id) > (SELECT token_budget FROM prompt_templates WHERE prompt_template_id = p_prompt_template_id)), FALSE), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_prompt_templates_condensation_percent
-- Field: PromptTemplates.CondensationPercent
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_prompt_templates_condensation_percent(p_prompt_template_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN COALESCE(((SELECT source_token_count FROM prompt_templates WHERE prompt_template_id = p_prompt_template_id))::NUMERIC, 0) = 0 THEN (0)::text ELSE (ROUND(((COALESCE(100, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT estimated_tokens FROM prompt_templates WHERE prompt_template_id = p_prompt_template_id)) AS v) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT source_token_count FROM prompt_templates WHERE prompt_template_id = p_prompt_template_id)) AS v) __safe_numeric), 0), 0))) AS v) __safe_numeric), 0)))::NUMERIC, (1)::INTEGER))::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_prompt_templates_is_verbatim_dump
-- Field: PromptTemplates.IsVerbatimDump
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_prompt_templates_is_verbatim_dump(p_prompt_template_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE(((SELECT source_token_count FROM prompt_templates WHERE prompt_template_id = p_prompt_template_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_prompt_templates_condensation_percent(p_prompt_template_id))::NUMERIC, 0) >= 90, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_knowledge_projections_version_modified_at
-- Field: KnowledgeProjections.VersionModifiedAt
-- Type: lookup | DataType: datetime | Returns: TIMESTAMPTZ
-- Lookup: ModifiedAt from related ProcedureVersions


CREATE OR REPLACE FUNCTION calc_knowledge_projections_version_modified_at(p_knowledge_projection_id TEXT)
RETURNS TIMESTAMPTZ AS $$
  SELECT (SELECT modified_at::timestamptz FROM procedure_versions WHERE procedure_version_id = (SELECT procedure_version FROM knowledge_projections WHERE knowledge_projection_id = p_knowledge_projection_id));
$$ LANGUAGE sql STABLE;

