-- calc_model_annotations_name
-- Field: ModelAnnotations.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_model_annotations_name(p_model_annotation_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(annotation_kind, '') FROM model_annotations WHERE model_annotation_id = p_model_annotation_id), ': ', LEFT(((SELECT NULLIF(body, '') FROM model_annotations WHERE model_annotation_id = p_model_annotation_id))::text, (50)::integer)))::text;
$$ LANGUAGE sql STABLE;

-- calc_model_annotations_is_discussion_in_authoritative_model
-- Field: ModelAnnotations.IsDiscussionInAuthoritativeModel
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_annotations_is_discussion_in_authoritative_model(p_model_annotation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((COALESCE(COALESCE((SELECT NULLIF(annotation_kind, '') FROM model_annotations WHERE model_annotation_id = p_model_annotation_id), '') = 'Comment', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(annotation_kind, '') FROM model_annotations WHERE model_annotation_id = p_model_annotation_id), '') = 'Question', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(annotation_kind, '') FROM model_annotations WHERE model_annotation_id = p_model_annotation_id), '') = 'Suggestion', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(annotation_kind, '') FROM model_annotations WHERE model_annotation_id = p_model_annotation_id), '') = 'AlternativeInterpretation', FALSE)), FALSE) AND COALESCE(COALESCE((SELECT NULLIF(stored_in, '') FROM model_annotations WHERE model_annotation_id = p_model_annotation_id), '') = 'AuthoritativeRulebook', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_annotations_flag_bypassed_annotation_interface
-- Field: ModelAnnotations.FlagBypassedAnnotationInterface
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_annotations_flag_bypassed_annotation_interface(p_model_annotation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(annotation_kind, '') FROM model_annotations WHERE model_annotation_id = p_model_annotation_id), '') = 'FlagOutdated', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(entered_through, '') FROM model_annotations WHERE model_annotation_id = p_model_annotation_id), '') <> 'AnnotationPanel', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_annotations_is_lost_new_knowledge
-- Field: ModelAnnotations.IsLostNewKnowledge
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_annotations_is_lost_new_knowledge(p_model_annotation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(annotation_kind, '') FROM model_annotations WHERE model_annotation_id = p_model_annotation_id), '') = 'NewKnowledge', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(status, '') FROM model_annotations WHERE model_annotation_id = p_model_annotation_id), '') <> 'Declined', FALSE) AND COALESCE((SELECT NULLIF(promoted_to_fragment, '') FROM model_annotations WHERE model_annotation_id = p_model_annotation_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_annotations_is_friction_without_gap
-- Field: ModelAnnotations.IsFrictionWithoutGap
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_annotations_is_friction_without_gap(p_model_annotation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(annotation_kind, '') FROM model_annotations WHERE model_annotation_id = p_model_annotation_id), '') = 'MissingKnowledge', FALSE) AND COALESCE((SELECT NULLIF(raised_knowledge_gap, '') FROM model_annotations WHERE model_annotation_id = p_model_annotation_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_annotations_is_open_outdated_flag
-- Field: ModelAnnotations.IsOpenOutdatedFlag
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_annotations_is_open_outdated_flag(p_model_annotation_id TEXT)
RETURNS BOOLEAN AS $$
