-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_knowledge_projections_semantic_type_iri(p_knowledge_projection_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT semantic_type_iri FROM knowledge_projections WHERE knowledge_projection_id = p_knowledge_projection_id);
$$ LANGUAGE sql STABLE;

-- calc_knowledge_search_events_name
-- Field: KnowledgeSearchEvents.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_search_events_name(p_knowledge_search_event_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(searched_by_agent, '') FROM knowledge_search_events WHERE knowledge_search_event_id = p_knowledge_search_event_id), ': ', LEFT(((SELECT NULLIF(query_text, '') FROM knowledge_search_events WHERE knowledge_search_event_id = p_knowledge_search_event_id))::text, (40)::integer)))::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_search_events_found_nothing_useful
-- Field: KnowledgeSearchEvents.FoundNothingUseful
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_search_events_found_nothing_useful(p_knowledge_search_event_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE(((SELECT result_count FROM knowledge_search_events WHERE knowledge_search_event_id = p_knowledge_search_event_id))::NUMERIC, 0) = 0, FALSE) OR COALESCE((COALESCE((SELECT NULLIF(opened_segment, '') FROM knowledge_search_events WHERE knowledge_search_event_id = p_knowledge_search_event_id) IS NULL, FALSE) AND COALESCE((SELECT NULLIF(opened_projection, '') FROM knowledge_search_events WHERE knowledge_search_event_id = p_knowledge_search_event_id) IS NULL, FALSE)), FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_knowledge_search_events_gave_up_after_seeing_results
-- Field: KnowledgeSearchEvents.GaveUpAfterSeeingResults
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_search_events_gave_up_after_seeing_results(p_knowledge_search_event_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT was_abandoned FROM knowledge_search_events WHERE knowledge_search_event_id = p_knowledge_search_event_id), FALSE), FALSE) AND COALESCE(COALESCE(((SELECT result_count FROM knowledge_search_events WHERE knowledge_search_event_id = p_knowledge_search_event_id))::NUMERIC, 0) > 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_knowledge_search_events_is_unlinked_failed_search
-- Field: KnowledgeSearchEvents.IsUnlinkedFailedSearch
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_search_events_is_unlinked_failed_search(p_knowledge_search_event_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_knowledge_search_events_found_nothing_useful(p_knowledge_search_event_id), FALSE) AND COALESCE((SELECT NULLIF(linked_knowledge_gap, '') FROM knowledge_search_events WHERE knowledge_search_event_id = p_knowledge_search_event_id) IS NULL, FALSE) AND COALESCE((SELECT NULLIF(linked_usability_barrier, '') FROM knowledge_search_events WHERE knowledge_search_event_id = p_knowledge_search_event_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

