-- calc_ai_adoption_initiatives_reviewed_output_count
-- Field: AiAdoptionInitiatives.ReviewedOutputCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_ai_adoption_initiatives_reviewed_output_count(p_ai_adoption_initiative_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM assistant_answers WHERE reviewed_for_initiative = (SELECT NULLIF(ai_adoption_initiative_id, '') FROM ai_adoption_initiatives WHERE ai_adoption_initiative_id = p_ai_adoption_initiative_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_ai_adoption_initiatives_last_outcome_measured_at
-- Field: AiAdoptionInitiatives.LastOutcomeMeasuredAt
-- Type: aggregation | DataType: datetime | Returns: TIMESTAMPTZ


CREATE OR REPLACE FUNCTION calc_ai_adoption_initiatives_last_outcome_measured_at(p_ai_adoption_initiative_id TEXT)
RETURNS TIMESTAMPTZ AS $$
  SELECT ((SELECT MAX(measured_at) FROM knowledge_outcome_measurements WHERE ai_initiative = p_ai_adoption_initiative_id))::timestamptz;
$$ LANGUAGE sql STABLE;

-- calc_ai_adoption_initiatives_days_since_outcome_measured
-- Field: AiAdoptionInitiatives.DaysSinceOutcomeMeasured
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_ai_adoption_initiatives_days_since_outcome_measured(p_ai_adoption_initiative_id TEXT)
RETURNS INTEGER AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_ai_adoption_initiatives_last_outcome_measured_at(p_ai_adoption_initiative_id) AS val) SELECT (CASE WHEN (SELECT val FROM __erb_dedup_v1) IS NULL THEN (0)::text ELSE ((((calc_ai_adoption_initiatives_as_of_instant(p_ai_adoption_initiative_id))::timestamptz AT TIME ZONE 'UTC')::date - (((SELECT val FROM __erb_dedup_v1))::timestamptz AT TIME ZONE 'UTC')::date))::text END)::integer;
$$ LANGUAGE sql STABLE;

