RETURNS INTEGER AS $$
  SELECT ((((calc_governed_models_as_of_instant(p_governed_model_id))::timestamptz AT TIME ZONE 'UTC')::date - (((SELECT registered_at::timestamptz FROM governed_models WHERE governed_model_id = p_governed_model_id))::timestamptz AT TIME ZONE 'UTC')::date))::integer;
$$ LANGUAGE sql STABLE;

