-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: Organization from related Roles


CREATE OR REPLACE FUNCTION calc_model_charters_authority_organization(p_model_charter_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT organization::text FROM roles WHERE role_id = (SELECT authority_role FROM model_charters WHERE model_charter_id = p_model_charter_id));
