-- calc_model_charters_last_drift_watch_at
-- Field: ModelCharters.LastDriftWatchAt
-- Type: aggregation | DataType: datetime | Returns: TIMESTAMPTZ


CREATE OR REPLACE FUNCTION calc_model_charters_last_drift_watch_at(p_model_charter_id TEXT)
RETURNS TIMESTAMPTZ AS $$
  SELECT ((SELECT MAX(performed_at) FROM steward_activities WHERE model_charter = p_model_charter_id AND duty_kind = 'DriftWatch'))::timestamptz;
$$ LANGUAGE sql STABLE;

-- calc_model_charters_days_since_drift_watch
-- Field: ModelCharters.DaysSinceDriftWatch
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_model_charters_days_since_drift_watch(p_model_charter_id TEXT)
RETURNS INTEGER AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_model_charters_last_drift_watch_at(p_model_charter_id) AS val), __erb_dedup_v2 AS (SELECT calc_model_charters_as_of_instant(p_model_charter_id) AS val) SELECT (CASE WHEN (SELECT val FROM __erb_dedup_v1) IS NULL THEN (((((SELECT val FROM __erb_dedup_v2))::timestamptz AT TIME ZONE 'UTC')::date - (((SELECT valid_from::timestamptz FROM model_charters WHERE model_charter_id = p_model_charter_id))::timestamptz AT TIME ZONE 'UTC')::date))::text ELSE (((((SELECT val FROM __erb_dedup_v2))::timestamptz AT TIME ZONE 'UTC')::date - (((SELECT val FROM __erb_dedup_v1))::timestamptz AT TIME ZONE 'UTC')::date))::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_model_charters_is_drift_watch_lapsed
-- Field: ModelCharters.IsDriftWatchLapsed
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_charters_is_drift_watch_lapsed(p_model_charter_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_model_charters_is_current(p_model_charter_id), FALSE) AND COALESCE(COALESCE((calc_model_charters_days_since_drift_watch(p_model_charter_id))::NUMERIC, 0) > 90, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_model_charters_procedure_decision_count
-- Field: ModelCharters.ProcedureDecisionCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_model_charters_procedure_decision_count(p_model_charter_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM change_requests WHERE authority_role = (SELECT NULLIF(authority_role, '') FROM model_charters WHERE model_charter_id = p_model_charter_id) AND calc_change_requests_is_decided(change_request_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_model_charters_model_review_count
-- Field: ModelCharters.ModelReviewCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_model_charters_model_review_count(p_model_charter_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM model_change_requests WHERE governed_model = (SELECT NULLIF(governed_model, '') FROM model_charters WHERE model_charter_id = p_model_charter_id) AND calc_model_change_requests_has_authority_review(model_change_request_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_model_charters_is_named_but_unexercised
-- Field: ModelCharters.IsNamedButUnexercised
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_charters_is_named_but_unexercised(p_model_charter_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_model_charters_is_current(p_model_charter_id), FALSE) AND COALESCE((COALESCE(COALESCE((calc_model_charters_steward_activity_count(p_model_charter_id))::NUMERIC, 0) = 0, FALSE) OR COALESCE(COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_model_charters_procedure_decision_count(p_model_charter_id)) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_model_charters_model_review_count(p_model_charter_id)) AS v) __safe_numeric), 0)))::NUMERIC, 0) = 0, FALSE)), FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_model_charters_steward_is_outside_tooling
-- Field: ModelCharters.StewardIsOutsideTooling
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_charters_steward_is_outside_tooling(p_model_charter_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_model_charters_model_tooling_owner_role(p_model_charter_id) AS val) SELECT ((COALESCE(COALESCE(calc_model_charters_model_kind(p_model_charter_id), '') = 'Ontology', FALSE) AND COALESCE((SELECT val FROM __erb_dedup_v1) IS NOT NULL, FALSE) AND COALESCE(COALESCE((SELECT NULLIF(steward_role, '') FROM model_charters WHERE model_charter_id = p_model_charter_id), '') <> COALESCE((SELECT val FROM __erb_dedup_v1), ''), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

