  SELECT ((COALESCE(COALESCE((SELECT NULLIF(status, '') FROM model_change_requests WHERE model_change_request_id = p_model_change_request_id), '') = 'Approved', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(status, '') FROM model_change_requests WHERE model_change_request_id = p_model_change_request_id), '') = 'Deployed', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

