$$ LANGUAGE sql STABLE;

-- calc_model_change_requests_has_authority_review
-- Field: ModelChangeRequests.HasAuthorityReview
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_change_requests_has_authority_review(p_model_change_request_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT authority_reviewed_at::timestamptz FROM model_change_requests WHERE model_change_request_id = p_model_change_request_id) IS NOT NULL)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_change_requests_requires_authority_review
-- Field: ModelChangeRequests.RequiresAuthorityReview
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_change_requests_requires_authority_review(p_model_change_request_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(change_operation, '') FROM model_change_requests WHERE model_change_request_id = p_model_change_request_id), '') = 'RenameClass', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(change_operation, '') FROM model_change_requests WHERE model_change_request_id = p_model_change_request_id), '') = 'RemoveClass', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(change_operation, '') FROM model_change_requests WHERE model_change_request_id = p_model_change_request_id), '') = 'ChangeDomainRange', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(change_operation, '') FROM model_change_requests WHERE model_change_request_id = p_model_change_request_id), '') = 'AddDisjointness', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(change_operation, '') FROM model_change_requests WHERE model_change_request_id = p_model_change_request_id), '') = 'AddVocabularyTerm', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(change_operation, '') FROM model_change_requests WHERE model_change_request_id = p_model_change_request_id), '') = 'RetireDefinition', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(declared_scale, '') FROM model_change_requests WHERE model_change_request_id = p_model_change_request_id), '') = 'Major', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_change_requests_is_minor_scope
-- Field: ModelChangeRequests.IsMinorScope
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_change_requests_is_minor_scope(p_model_change_request_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE(calc_model_change_requests_requires_authority_review(p_model_change_request_id), FALSE) = FALSE, FALSE) AND COALESCE(COALESCE((SELECT NULLIF(declared_scale, '') FROM model_change_requests WHERE model_change_request_id = p_model_change_request_id), '') <> 'Major', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_change_requests_steward_own_change_unreviewed
-- Field: ModelChangeRequests.StewardOwnChangeUnreviewed
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_change_requests_steward_own_change_unreviewed(p_model_change_request_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_model_change_requests_steward_agent(p_model_change_request_id) AS val) SELECT ((COALESCE((SELECT val FROM __erb_dedup_v1) IS NOT NULL, FALSE) AND COALESCE(COALESCE((SELECT NULLIF(requested_by_agent, '') FROM model_change_requests WHERE model_change_request_id = p_model_change_request_id), '') = COALESCE((SELECT val FROM __erb_dedup_v1), ''), FALSE) AND COALESCE(COALESCE(calc_model_change_requests_is_minor_scope(p_model_change_request_id), FALSE) = FALSE, FALSE) AND COALESCE(COALESCE(calc_model_change_requests_has_authority_review(p_model_change_request_id), FALSE) = FALSE, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_change_requests_steward_approval_out_of_bounds
