$$ LANGUAGE sql STABLE;

-- calc_external_dependency_revisions_days_since_published
-- Field: ExternalDependencyRevisions.DaysSincePublished
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_external_dependency_revisions_days_since_published(p_external_dependency_revision_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((((calc_external_dependency_revisions_as_of_instant(p_external_dependency_revision_id))::timestamptz AT TIME ZONE 'UTC')::date - (((SELECT published_at::timestamptz FROM external_dependency_revisions WHERE external_dependency_revision_id = p_external_dependency_revision_id))::timestamptz AT TIME ZONE 'UTC')::date))::integer;
$$ LANGUAGE sql STABLE;

-- calc_external_dependency_revisions_is_untracked_revision
-- Field: ExternalDependencyRevisions.IsUntrackedRevision
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_external_dependency_revisions_is_untracked_revision(p_external_dependency_revision_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT tracked_at::timestamptz FROM external_dependency_revisions WHERE external_dependency_revision_id = p_external_dependency_revision_id) IS NULL, FALSE) AND COALESCE(COALESCE((calc_external_dependency_revisions_affected_mapping_count(p_external_dependency_revision_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_external_dependency_revisions_days_since_published(p_external_dependency_revision_id))::NUMERIC, 0) > 30, FALSE)));
$$ LANGUAGE sql STABLE;

