-- calc_model_expansion_requests_requires_schema_extension
-- Field: ModelExpansionRequests.RequiresSchemaExtension
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_expansion_requests_requires_schema_extension(p_model_expansion_request_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_model_expansion_requests_uncovered_concept_count(p_model_expansion_request_id))::NUMERIC, 0) > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_expansion_requests_fit_decision_contradicts_concept_
-- Field: ModelExpansionRequests.FitDecisionContradictsConceptFit
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_expansion_requests_fit_decision_contradicts_concept_(p_model_expansion_request_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(fit_decision, '') FROM model_expansion_requests WHERE model_expansion_request_id = p_model_expansion_request_id), '') = 'FitsExistingSchema', FALSE) AND COALESCE(COALESCE((calc_model_expansion_requests_uncovered_concept_count(p_model_expansion_request_id))::NUMERIC, 0) > 0, FALSE)));
$$ LANGUAGE sql STABLE;

