RETURNS TEXT AS $$
  SELECT (LEFT(((SELECT NULLIF(decision, '') FROM process_design_decisions WHERE process_design_decision_id = p_process_design_decision_id))::text, (60)::integer))::text;
$$ LANGUAGE sql STABLE;

-- calc_process_design_decisions_is_commitment_without_rationale
-- Field: ProcessDesignDecisions.IsCommitmentWithoutRationale
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_process_design_decisions_is_commitment_without_rationale(p_process_design_decision_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(decision, '') FROM process_design_decisions WHERE process_design_decision_id = p_process_design_decision_id) IS NOT NULL, FALSE) AND COALESCE((SELECT NULLIF(rationale, '') FROM process_design_decisions WHERE process_design_decision_id = p_process_design_decision_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_process_design_decisions_days_before_recorded
-- Field: ProcessDesignDecisions.DaysBeforeRecorded
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_process_design_decisions_days_before_recorded(p_process_design_decision_id TEXT)
RETURNS INTEGER AS $$
  SELECT (((((SELECT recorded_at::timestamptz FROM process_design_decisions WHERE process_design_decision_id = p_process_design_decision_id))::timestamptz AT TIME ZONE 'UTC')::date - (((SELECT decided_at::timestamptz FROM process_design_decisions WHERE process_design_decision_id = p_process_design_decision_id))::timestamptz AT TIME ZONE 'UTC')::date))::integer;
$$ LANGUAGE sql STABLE;

-- calc_process_design_decisions_is_recorded_after_the_fact
-- Field: ProcessDesignDecisions.IsRecordedAfterTheFact
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_process_design_decisions_is_recorded_after_the_fact(p_process_design_decision_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_process_design_decisions_days_before_recorded(p_process_design_decision_id))::NUMERIC, 0) > 30)::boolean;
$$ LANGUAGE sql STABLE;

