$$ LANGUAGE sql STABLE;

-- calc_model_change_log_entries_alters_logical_model
-- Field: ModelChangeLogEntries.AltersLogicalModel
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_change_log_entries_alters_logical_model(p_model_change_log_entry_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(change_layer, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'Schema', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(change_layer, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'Vocabulary', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_change_log_entries_is_class_removal_or_rename
-- Field: ModelChangeLogEntries.IsClassRemovalOrRename
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_change_log_entries_is_class_removal_or_rename(p_model_change_log_entry_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(change_operation, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'RemoveClass', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(change_operation, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'RenameClass', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_change_log_entries_is_invalidating_domain_range_chan
-- Field: ModelChangeLogEntries.IsInvalidatingDomainRangeChange
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_change_log_entries_is_invalidating_domain_range_chan(p_model_change_log_entry_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(change_operation, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'ChangeDomainRange', FALSE) AND COALESCE(COALESCE((SELECT invalidates_instances FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), FALSE), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_change_log_entries_is_inconsistent_disjointness
-- Field: ModelChangeLogEntries.IsInconsistentDisjointness
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_change_log_entries_is_inconsistent_disjointness(p_model_change_log_entry_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(change_operation, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'AddDisjointness', FALSE) AND COALESCE(COALESCE((SELECT invalidates_instances FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), FALSE), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_change_log_entries_is_backward_incompatible
-- Field: ModelChangeLogEntries.IsBackwardIncompatible
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_change_log_entries_is_backward_incompatible(p_model_change_log_entry_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_model_change_log_entries_is_class_removal_or_rename(p_model_change_log_entry_id), FALSE) OR COALESCE(COALESCE((SELECT invalidates_instances FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), FALSE), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_change_log_entries_is_additive_schema_change
-- Field: ModelChangeLogEntries.IsAdditiveSchemaChange
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_change_log_entries_is_additive_schema_change(p_model_change_log_entry_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(change_layer, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'Schema', FALSE) AND COALESCE((COALESCE(COALESCE((SELECT NULLIF(change_operation, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'AddClass', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(change_operation, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'AddProperty', FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_change_log_entries_is_unexplained_modification
-- Field: ModelChangeLogEntries.IsUnexplainedModification
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_change_log_entries_is_unexplained_modification(p_model_change_log_entry_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((COALESCE(COALESCE((SELECT NULLIF(change_layer, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'Schema', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(change_layer, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id), '') = 'Instance', FALSE)), FALSE) AND COALESCE((SELECT NULLIF(rationale, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_change_log_entries_rationale_without_question
-- Field: ModelChangeLogEntries.RationaleWithoutQuestion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_change_log_entries_rationale_without_question(p_model_change_log_entry_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(rationale, '') FROM model_change_log_entries WHERE model_change_log_entry_id = p_model_change_log_entry_id) IS NOT NULL, FALSE) AND COALESCE(calc_model_change_log_entries_motivating_question(p_model_change_log_entry_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_model_change_log_entries_is_schema_change_without_incremen
-- Field: ModelChangeLogEntries.IsSchemaChangeWithoutIncrement
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_model_change_log_entries_is_schema_change_without_incremen(p_model_change_log_entry_id TEXT)
RETURNS BOOLEAN AS $$
