  SELECT (CONCAT((SELECT NULLIF(governed_model, '') FROM drift_observations WHERE drift_observation_id = p_drift_observation_id), ': ', LEFT(((SELECT NULLIF(description, '') FROM drift_observations WHERE drift_observation_id = p_drift_observation_id))::text, (50)::integer)))::text;
$$ LANGUAGE sql STABLE;

-- calc_drift_observations_is_open_practice_mismatch
-- Field: DriftObservations.IsOpenPracticeMismatch
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_drift_observations_is_open_practice_mismatch(p_drift_observation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(drift_kind, '') FROM drift_observations WHERE drift_observation_id = p_drift_observation_id), '') = 'PracticeMismatch', FALSE) AND COALESCE((SELECT resolved_at::timestamptz FROM drift_observations WHERE drift_observation_id = p_drift_observation_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_drift_observations_went_undetected_by_passing_suite
-- Field: DriftObservations.WentUndetectedByPassingSuite
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_drift_observations_went_undetected_by_passing_suite(p_drift_observation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(since_release, '') FROM drift_observations WHERE drift_observation_id = p_drift_observation_id) IS NOT NULL, FALSE) AND COALESCE(calc_drift_observations_release_passed_validation(p_drift_observation_id), FALSE) AND COALESCE(COALESCE((SELECT NULLIF(detected_by, '') FROM drift_observations WHERE drift_observation_id = p_drift_observation_id), '') <> 'ValidationSuite', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_drift_observations_drift_follows_clean_release
-- Field: DriftObservations.DriftFollowsCleanRelease
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_drift_observations_drift_follows_clean_release(p_drift_observation_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(since_release, '') FROM drift_observations WHERE drift_observation_id = p_drift_observation_id) IS NOT NULL, FALSE) AND COALESCE(calc_drift_observations_release_passed_validation(p_drift_observation_id), FALSE) AND COALESCE(COALESCE(((SELECT observed_at::timestamptz FROM drift_observations WHERE drift_observation_id = p_drift_observation_id) > calc_drift_observations_release_issued_at(p_drift_observation_id)), FALSE), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_name
-- Field: SourcingFunctions.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_sourcing_functions_name(p_sourcing_function_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(client_organization, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id), ': ', (SELECT NULLIF(label, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_is_outsourced
-- Field: SourcingFunctions.IsOutsourced
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_sourcing_functions_is_outsourced(p_sourcing_function_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((SELECT NULLIF(executing_organization, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id), '') <> COALESCE((SELECT NULLIF(client_organization, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id), ''))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_is_business_process_outsourcing
-- Field: SourcingFunctions.IsBusinessProcessOutsourcing
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_sourcing_functions_is_business_process_outsourcing(p_sourcing_function_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_sourcing_functions_is_outsourced(p_sourcing_function_id), FALSE) AND COALESCE(COALESCE((SELECT NULLIF(work_nature, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id), '') = 'Transactional', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_is_knowledge_process_outsourcing
-- Field: SourcingFunctions.IsKnowledgeProcessOutsourcing
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_sourcing_functions_is_knowledge_process_outsourcing(p_sourcing_function_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_sourcing_functions_is_outsourced(p_sourcing_function_id), FALSE) AND COALESCE(COALESCE((SELECT NULLIF(work_nature, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id), '') = 'ExpertiseHeavy', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_is_vital_expertise_classed_non_core
-- Field: SourcingFunctions.IsVitalExpertiseClassedNonCore
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_sourcing_functions_is_vital_expertise_classed_non_core(p_sourcing_function_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(sourcing_class, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id), '') = 'SentOutExecution', FALSE) AND COALESCE(COALESCE((SELECT is_strategically_vital FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id), FALSE), FALSE) AND COALESCE(COALESCE((SELECT NULLIF(work_nature, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id), '') = 'ExpertiseHeavy', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_is_what_how_split
-- Field: SourcingFunctions.IsWhatHowSplit
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_sourcing_functions_is_what_how_split(p_sourcing_function_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((SELECT NULLIF(specification_holder, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id), '') <> COALESCE((SELECT NULLIF(method_holder, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id), ''))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_is_method_knowledge_held_outside
-- Field: SourcingFunctions.IsMethodKnowledgeHeldOutside
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_sourcing_functions_is_method_knowledge_held_outside(p_sourcing_function_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((SELECT NULLIF(method_holder, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id), '') <> COALESCE((SELECT NULLIF(client_organization, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id), ''))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_claims_how_without_doing
-- Field: SourcingFunctions.ClaimsHowWithoutDoing
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_sourcing_functions_claims_how_without_doing(p_sourcing_function_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(method_holder, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id), '') = COALESCE((SELECT NULLIF(client_organization, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id), ''), FALSE) AND COALESCE(calc_sourcing_functions_is_outsourced(p_sourcing_function_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_is_vital_expertise_process
-- Field: SourcingFunctions.IsVitalExpertiseProcess
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_sourcing_functions_is_vital_expertise_process(p_sourcing_function_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT is_strategically_vital FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id), FALSE), FALSE) AND COALESCE(COALESCE((SELECT NULLIF(work_nature, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id), '') = 'ExpertiseHeavy', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_is_outsourced_vital_expertise_process
-- Field: SourcingFunctions.IsOutsourcedVitalExpertiseProcess
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_sourcing_functions_is_outsourced_vital_expertise_process(p_sourcing_function_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_sourcing_functions_is_vital_expertise_process(p_sourcing_function_id), FALSE) AND COALESCE(calc_sourcing_functions_is_outsourced(p_sourcing_function_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_audit_item_count
-- Field: SourcingFunctions.AuditItemCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_sourcing_functions_audit_item_count(p_sourcing_function_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM knowledge_audit_items WHERE sourcing_function = (SELECT NULLIF(sourcing_function_id, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_dependency_count
-- Field: SourcingFunctions.DependencyCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_sourcing_functions_dependency_count(p_sourcing_function_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM knowledge_audit_items WHERE sourcing_function = (SELECT NULLIF(sourcing_function_id, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id) AND calc_knowledge_audit_items_is_knowledge_dependency(knowledge_audit_item_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_coverage_gap_count
-- Field: SourcingFunctions.CoverageGapCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_sourcing_functions_coverage_gap_count(p_sourcing_function_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM knowledge_audit_items WHERE sourcing_function = (SELECT NULLIF(sourcing_function_id, '') FROM sourcing_functions WHERE sourcing_function_id = p_sourcing_function_id) AND calc_knowledge_audit_items_is_coverage_gap(knowledge_audit_item_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_sourcing_functions_specification_audit_count
-- Field: SourcingFunctions.SpecificationAuditCount
