RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM knowledge_audit_items WHERE knowledge_audit = (SELECT NULLIF(knowledge_audit_id, '') FROM knowledge_audits WHERE knowledge_audit_id = p_knowledge_audit_id) AND calc_knowledge_audit_items_has_internal_shortfall(knowledge_audit_item_id) = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_audits_treats_deficit_as_cost_problem
-- Field: KnowledgeAudits.TreatsDeficitAsCostProblem
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_audits_treats_deficit_as_cost_problem(p_knowledge_audit_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_knowledge_audits_finding_count(p_knowledge_audit_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((SELECT NULLIF(problem_framing, '') FROM knowledge_audits WHERE knowledge_audit_id = p_knowledge_audit_id), '') <> 'KnowledgeDeficit', FALSE)));
$$ LANGUAGE sql STABLE;

