-- calc_knowledge_audit_items_name
-- Field: KnowledgeAuditItems.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_audit_items_name(p_knowledge_audit_item_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(knowledge_audit, '') FROM knowledge_audit_items WHERE knowledge_audit_item_id = p_knowledge_audit_item_id), ' / ', (SELECT NULLIF(knowledge_area, '') FROM knowledge_audit_items WHERE knowledge_audit_item_id = p_knowledge_audit_item_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_audit_items_has_internal_shortfall
-- Field: KnowledgeAuditItems.HasInternalShortfall
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_audit_items_has_internal_shortfall(p_knowledge_audit_item_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE(((SELECT held_internal_level FROM knowledge_audit_items WHERE knowledge_audit_item_id = p_knowledge_audit_item_id) < (SELECT needed_level FROM knowledge_audit_items WHERE knowledge_audit_item_id = p_knowledge_audit_item_id)), FALSE))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_audit_items_is_knowledge_dependency
-- Field: KnowledgeAuditItems.IsKnowledgeDependency
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_audit_items_is_knowledge_dependency(p_knowledge_audit_item_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_knowledge_audit_items_has_internal_shortfall(p_knowledge_audit_item_id), FALSE) AND COALESCE((SELECT NULLIF(provider_holding_knowledge, '') FROM knowledge_audit_items WHERE knowledge_audit_item_id = p_knowledge_audit_item_id) IS NOT NULL, FALSE) AND COALESCE(COALESCE(((SELECT provider_held_level FROM knowledge_audit_items WHERE knowledge_audit_item_id = p_knowledge_audit_item_id) >= (SELECT needed_level FROM knowledge_audit_items WHERE knowledge_audit_item_id = p_knowledge_audit_item_id)), (((SELECT provider_held_level FROM knowledge_audit_items WHERE knowledge_audit_item_id = p_knowledge_audit_item_id)) IS NULL AND ((SELECT needed_level FROM knowledge_audit_items WHERE knowledge_audit_item_id = p_knowledge_audit_item_id)) IS NULL)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_audit_items_is_coverage_gap
-- Field: KnowledgeAuditItems.IsCoverageGap
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_audit_items_is_coverage_gap(p_knowledge_audit_item_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_knowledge_audit_items_has_internal_shortfall(p_knowledge_audit_item_id), FALSE) AND COALESCE(NOT (COALESCE(calc_knowledge_audit_items_is_knowledge_dependency(p_knowledge_audit_item_id), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_audit_items_is_unnamed_finding
-- Field: KnowledgeAuditItems.IsUnnamedFinding
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_audit_items_is_unnamed_finding(p_knowledge_audit_item_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_knowledge_audit_items_has_internal_shortfall(p_knowledge_audit_item_id), FALSE) AND COALESCE((SELECT NULLIF(named_knowledge_gap, '') FROM knowledge_audit_items WHERE knowledge_audit_item_id = p_knowledge_audit_item_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_audit_items_is_single_team_silo
-- Field: KnowledgeAuditItems.IsSingleTeamSilo
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_audit_items_is_single_team_silo(p_knowledge_audit_item_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE(((SELECT held_internal_level FROM knowledge_audit_items WHERE knowledge_audit_item_id = p_knowledge_audit_item_id) >= (SELECT needed_level FROM knowledge_audit_items WHERE knowledge_audit_item_id = p_knowledge_audit_item_id)), (((SELECT held_internal_level FROM knowledge_audit_items WHERE knowledge_audit_item_id = p_knowledge_audit_item_id)) IS NULL AND ((SELECT needed_level FROM knowledge_audit_items WHERE knowledge_audit_item_id = p_knowledge_audit_item_id)) IS NULL)), FALSE) AND COALESCE(COALESCE(((SELECT internal_holding_team_count FROM knowledge_audit_items WHERE knowledge_audit_item_id = p_knowledge_audit_item_id))::NUMERIC, 0) = 1, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_knowledge_capture_initiatives_name
