$$ LANGUAGE sql STABLE;

-- calc_provider_engagements_lacks_knowledge_deliverables
-- Field: ProviderEngagements.LacksKnowledgeDeliverables
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_provider_engagements_lacks_knowledge_deliverables(p_provider_engagement_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_provider_engagements_is_active(p_provider_engagement_id), FALSE) AND COALESCE(COALESCE((calc_provider_engagements_required_deliverable_count(p_provider_engagement_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_provider_engagements_is_one_way_learning
-- Field: ProviderEngagements.IsOneWayLearning
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_provider_engagements_is_one_way_learning(p_provider_engagement_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_provider_engagements_is_active(p_provider_engagement_id), FALSE) AND COALESCE(COALESCE((calc_provider_engagements_required_deliverable_count(p_provider_engagement_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE((COALESCE(COALESCE((calc_provider_engagements_to_client_delivered_count(p_provider_engagement_id))::NUMERIC, 0) = 0, FALSE) OR COALESCE(COALESCE((calc_provider_engagements_to_provider_delivered_count(p_provider_engagement_id))::NUMERIC, 0) = 0, FALSE)), FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_provider_engagements_is_short_term_without_joint_knowledge
-- Field: ProviderEngagements.IsShortTermWithoutJointKnowledge
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_provider_engagements_is_short_term_without_joint_knowledge(p_provider_engagement_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_provider_engagements_is_active(p_provider_engagement_id), FALSE) AND COALESCE(COALESCE(((SELECT term_months FROM provider_engagements WHERE provider_engagement_id = p_provider_engagement_id))::NUMERIC, 0) < 36, FALSE) AND COALESCE(COALESCE((calc_provider_engagements_joint_deliverable_count(p_provider_engagement_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_provider_engagements_obliges_knowledge_flow_back
-- Field: ProviderEngagements.ObligesKnowledgeFlowBack
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_provider_engagements_obliges_knowledge_flow_back(p_provider_engagement_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_provider_engagements_to_client_required_count(p_provider_engagement_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE((SELECT NULLIF(knowledge_return_plan, '') FROM provider_engagements WHERE provider_engagement_id = p_provider_engagement_id) IS NOT NULL, FALSE)));
$$ LANGUAGE sql STABLE;

