-- calc_records_retention_policies_name
-- Field: RecordsRetentionPolicies.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_records_retention_policies_name(p_records_retention_policy_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(record_class, '') FROM records_retention_policies WHERE records_retention_policy_id = p_records_retention_policy_id), ' / ', (SELECT NULLIF(retention_driver, '') FROM records_retention_policies WHERE records_retention_policy_id = p_records_retention_policy_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_records_retention_policies_is_legal_led_knowledge_destruct
-- Field: RecordsRetentionPolicies.IsLegalLedKnowledgeDestruction
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_records_retention_policies_is_legal_led_knowledge_destruct(p_records_retention_policy_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE(calc_records_retention_policies_program_sponsor_discipline(p_records_retention_policy_id), '') = 'Legal', FALSE) AND COALESCE(COALESCE((SELECT NULLIF(retention_driver, '') FROM records_retention_policies WHERE records_retention_policy_id = p_records_retention_policy_id), '') = 'ComplianceRisk', FALSE) AND COALESCE(COALESCE(((SELECT retention_years FROM records_retention_policies WHERE records_retention_policy_id = p_records_retention_policy_id) < (SELECT knowledge_useful_life_years FROM records_retention_policies WHERE records_retention_policy_id = p_records_retention_policy_id)), FALSE), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

