$$ LANGUAGE sql STABLE;

-- calc_ai_registry_model_versions_is_live_but_unregistered_in_gra
-- Field: AiRegistryModelVersions.IsLiveButUnregisteredInGraph
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_ai_registry_model_versions_is_live_but_unregistered_in_gra(p_ai_registry_model_version_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_ai_registry_model_versions_live_production_deployment_coun(p_ai_registry_model_version_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((calc_ai_registry_model_versions_graph_individual_count(p_ai_registry_model_version_id))::NUMERIC, 0) = 0, FALSE)));
$$ LANGUAGE sql STABLE;

