-- calc_observed_actions_is_unofficial_workaround
-- Field: ObservedActions.IsUnofficialWorkaround
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_observed_actions_is_unofficial_workaround(p_observed_action_id TEXT)
