CREATE OR REPLACE FUNCTION calc_elicitation_participants_is_knowledge_producer(p_elicitation_participant_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(knowledge_flow, '') FROM elicitation_participants WHERE elicitation_participant_id = p_elicitation_participant_id), '') = 'Producer', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(knowledge_flow, '') FROM elicitation_participants WHERE elicitation_participant_id = p_elicitation_participant_id), '') = 'Both', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_elicitation_participants_is_knowledge_consumer
-- Field: ElicitationParticipants.IsKnowledgeConsumer
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_elicitation_participants_is_knowledge_consumer(p_elicitation_participant_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(knowledge_flow, '') FROM elicitation_participants WHERE elicitation_participant_id = p_elicitation_participant_id), '') = 'Consumer', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(knowledge_flow, '') FROM elicitation_participants WHERE elicitation_participant_id = p_elicitation_participant_id), '') = 'Both', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

