RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(step, '') FROM workflow_view_divergences WHERE workflow_view_divergence_id = p_workflow_view_divergence_id), ': ', LEFT(((SELECT NULLIF(view_a, '') FROM workflow_view_divergences WHERE workflow_view_divergence_id = p_workflow_view_divergence_id))::text, (40)::integer), ' / ', LEFT(((SELECT NULLIF(view_b, '') FROM workflow_view_divergences WHERE workflow_view_divergence_id = p_workflow_view_divergence_id))::text, (40)::integer)))::text;
