  SELECT (CONCAT((SELECT NULLIF(cognition_kind, '') FROM expert_cognitions WHERE expert_cognition_id = p_expert_cognition_id), ': ', LEFT(((SELECT NULLIF(statement, '') FROM expert_cognitions WHERE expert_cognition_id = p_expert_cognition_id))::text, (60)::integer)))::text;
$$ LANGUAGE sql STABLE;

-- calc_expert_cognitions_is_mental_model
-- Field: ExpertCognitions.IsMentalModel
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_expert_cognitions_is_mental_model(p_expert_cognition_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((SELECT NULLIF(cognition_kind, '') FROM expert_cognitions WHERE expert_cognition_id = p_expert_cognition_id), '') = 'MentalModel')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_expert_cognitions_is_automatic_heuristic
-- Field: ExpertCognitions.IsAutomaticHeuristic
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_expert_cognitions_is_automatic_heuristic(p_expert_cognition_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(cognition_kind, '') FROM expert_cognitions WHERE expert_cognition_id = p_expert_cognition_id), '') = 'DecisionHeuristic', FALSE) AND COALESCE(COALESCE((SELECT applied_automatically FROM expert_cognitions WHERE expert_cognition_id = p_expert_cognition_id), FALSE), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_expert_cognitions_is_heuristic_oversimplified
-- Field: ExpertCognitions.IsHeuristicOversimplified
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_expert_cognitions_is_heuristic_oversimplified(p_expert_cognition_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(cognition_kind, '') FROM expert_cognitions WHERE expert_cognition_id = p_expert_cognition_id), '') = 'DecisionHeuristic', FALSE) AND COALESCE(COALESCE((SELECT expert_stated_exceptions FROM expert_cognitions WHERE expert_cognition_id = p_expert_cognition_id), FALSE), FALSE) AND COALESCE((SELECT NULLIF(captured_exceptions, '') FROM expert_cognitions WHERE expert_cognition_id = p_expert_cognition_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_concept_ladder_rungs_name
-- Field: ConceptLadderRungs.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_concept_ladder_rungs_name(p_concept_ladder_rung_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(step, '') FROM concept_ladder_rungs WHERE concept_ladder_rung_id = p_concept_ladder_rung_id), ' ', (SELECT NULLIF(rung_kind, '') FROM concept_ladder_rungs WHERE concept_ladder_rung_id = p_concept_ladder_rung_id), ': ', LEFT(((SELECT NULLIF(statement, '') FROM concept_ladder_rungs WHERE concept_ladder_rung_id = p_concept_ladder_rung_id))::text, (50)::integer)))::text;
$$ LANGUAGE sql STABLE;

-- calc_concept_ladder_rungs_step_top_level
-- Field: ConceptLadderRungs.StepTopLevel
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_concept_ladder_rungs_step_top_level(p_concept_ladder_rung_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(MAX((ladder_level)::numeric), 0) FROM concept_ladder_rungs WHERE step = (SELECT NULLIF(step, '') FROM concept_ladder_rungs WHERE concept_ladder_rung_id = p_concept_ladder_rung_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_concept_ladder_rungs_is_ultimate_goal
-- Field: ConceptLadderRungs.IsUltimateGoal
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_concept_ladder_rungs_is_ultimate_goal(p_concept_ladder_rung_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE(((SELECT ladder_level FROM concept_ladder_rungs WHERE concept_ladder_rung_id = p_concept_ladder_rung_id))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((SELECT ladder_level FROM concept_ladder_rungs WHERE concept_ladder_rung_id = p_concept_ladder_rung_id), 0) = COALESCE(calc_concept_ladder_rungs_step_top_level(p_concept_ladder_rung_id), 0), FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_concept_ladder_rungs_is_decomposition_rung
-- Field: ConceptLadderRungs.IsDecompositionRung
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_concept_ladder_rungs_is_decomposition_rung(p_concept_ladder_rung_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE(((SELECT ladder_level FROM concept_ladder_rungs WHERE concept_ladder_rung_id = p_concept_ladder_rung_id))::NUMERIC, 0) < 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_repertory_grid_constructs_name
