$$ LANGUAGE sql STABLE;

-- calc_repertory_grid_constructs_dimension
-- Field: RepertoryGridConstructs.Dimension
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_repertory_grid_constructs_dimension(p_repertory_grid_construct_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(pole_a, '') FROM repertory_grid_constructs WHERE repertory_grid_construct_id = p_repertory_grid_construct_id), ' vs ', (SELECT NULLIF(pole_b, '') FROM repertory_grid_constructs WHERE repertory_grid_construct_id = p_repertory_grid_construct_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_repertory_grid_constructs_is_never_stated_dimension
-- Field: RepertoryGridConstructs.IsNeverStatedDimension
