RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(snapshot, '') FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id), ' ', (SELECT NULLIF(carrier, '') FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id), ': ', LEFT(((SELECT NULLIF(statement, '') FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id))::text, (50)::integer)))::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_holdings_is_unformalized_process_knowledge
