-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_holdings_is_unformalized_process_knowledge(p_knowledge_holding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(formalized_as, '') FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id) IS NULL, FALSE) AND COALESCE(COALESCE((SELECT NULLIF(carrier, '') FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id), '') <> 'ProcedureRulebook', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_holdings_is_procedural_knowledge
-- Field: KnowledgeHoldings.IsProceduralKnowledge
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_holdings_is_procedural_knowledge(p_knowledge_holding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(formalized_as, '') FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id) IS NOT NULL)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_holdings_is_judgment_outside_document
-- Field: KnowledgeHoldings.IsJudgmentOutsideDocument
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_holdings_is_judgment_outside_document(p_knowledge_holding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT is_unsaid_in_sop FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id), FALSE), FALSE) AND COALESCE(calc_knowledge_holdings_is_unformalized_process_knowledge(p_knowledge_holding_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_holdings_is_veteran_discretion
-- Field: KnowledgeHoldings.IsVeteranDiscretion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_holdings_is_veteran_discretion(p_knowledge_holding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT holder_is_veteran FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id), FALSE), FALSE) AND COALESCE(COALESCE((SELECT handles_exception_or_discretion FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id), FALSE), FALSE) AND COALESCE(calc_knowledge_holdings_is_unformalized_process_knowledge(p_knowledge_holding_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_holdings_is_formalized_without_elicitation_work
-- Field: KnowledgeHoldings.IsFormalizedWithoutElicitationWork
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_holdings_is_formalized_without_elicitation_work(p_knowledge_holding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT NULLIF(formalized_as, '') FROM knowledge_holdings WHERE knowledge_holding_id = p_knowledge_holding_id) IS NOT NULL, FALSE) AND COALESCE(calc_knowledge_holdings_formalized_fragment_session(p_knowledge_holding_id) IS NULL, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_fragment_corroborations_name
-- Field: FragmentCorroborations.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_fragment_corroborations_name(p_fragment_corroboration_id TEXT)
