  SELECT (CONCAT((SELECT NULLIF(knowledge_fragment, '') FROM fragment_corroborations WHERE fragment_corroboration_id = p_fragment_corroboration_id), ' via ', (SELECT NULLIF(elicitation_session, '') FROM fragment_corroborations WHERE fragment_corroboration_id = p_fragment_corroboration_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_test_outcomes_name
-- Field: KnowledgeTestOutcomes.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_test_outcomes_name(p_knowledge_test_outcome_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(procedure, '') FROM knowledge_test_outcomes WHERE knowledge_test_outcome_id = p_knowledge_test_outcome_id), ': ', (SELECT NULLIF(outcome_area, '') FROM knowledge_test_outcomes WHERE knowledge_test_outcome_id = p_knowledge_test_outcome_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_test_outcomes_is_improved
-- Field: KnowledgeTestOutcomes.IsImproved
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_test_outcomes_is_improved(p_knowledge_test_outcome_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((COALESCE(COALESCE((SELECT higher_is_better FROM knowledge_test_outcomes WHERE knowledge_test_outcome_id = p_knowledge_test_outcome_id), FALSE), FALSE) AND COALESCE(COALESCE(((SELECT after_test_value FROM knowledge_test_outcomes WHERE knowledge_test_outcome_id = p_knowledge_test_outcome_id) > (SELECT baseline_value FROM knowledge_test_outcomes WHERE knowledge_test_outcome_id = p_knowledge_test_outcome_id)), FALSE), FALSE)), FALSE) OR COALESCE((COALESCE(NOT (COALESCE(COALESCE((SELECT higher_is_better FROM knowledge_test_outcomes WHERE knowledge_test_outcome_id = p_knowledge_test_outcome_id), FALSE), FALSE)), FALSE) AND COALESCE(COALESCE(((SELECT after_test_value FROM knowledge_test_outcomes WHERE knowledge_test_outcome_id = p_knowledge_test_outcome_id) < (SELECT baseline_value FROM knowledge_test_outcomes WHERE knowledge_test_outcome_id = p_knowledge_test_outcome_id)), FALSE), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

