  SELECT ((COALESCE((COALESCE(COALESCE((SELECT NULLIF(replacement_plan, '') FROM know_how_carriers WHERE know_how_carrier_id = p_know_how_carrier_id), '') = 'PublicReference', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(replacement_plan, '') FROM know_how_carriers WHERE know_how_carrier_id = p_know_how_carrier_id), '') = 'AiGeneration', FALSE)), FALSE) AND COALESCE(COALESCE((SELECT is_in_public_references FROM know_how_carriers WHERE know_how_carrier_id = p_know_how_carrier_id), FALSE) = FALSE, FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

