RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT NULLIF(channel, '') FROM knowledge_transfers WHERE knowledge_transfer_id = p_knowledge_transfer_id), '') = 'PersonalRelationship', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(channel, '') FROM knowledge_transfers WHERE knowledge_transfer_id = p_knowledge_transfer_id), '') = 'Collaboration', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(channel, '') FROM knowledge_transfers WHERE knowledge_transfer_id = p_knowledge_transfer_id), '') = 'DesignProductionIteration', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(channel, '') FROM knowledge_transfers WHERE knowledge_transfer_id = p_knowledge_transfer_id), '') = 'EmployerChange', FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

