-- calc_knowledge_repository_entries_name
-- Field: KnowledgeRepositoryEntries.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_repository_entries_name(p_knowledge_repository_entry_id TEXT)
