RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_knowledge_traces_source_material_kind(p_knowledge_trace_id) AS val) SELECT ((COALESCE((COALESCE(COALESCE((SELECT NULLIF(traced_aspect, '') FROM knowledge_traces WHERE knowledge_trace_id = p_knowledge_trace_id), '') = 'Workaround', FALSE) AND COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') <> 'FieldNotes', FALSE)), FALSE) OR COALESCE((COALESCE(COALESCE((SELECT NULLIF(traced_aspect, '') FROM knowledge_traces WHERE knowledge_trace_id = p_knowledge_trace_id), '') = 'ActualExecution', FALSE) AND COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), '') <> 'MinedEventTrace', FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

